"""Machine-readable experiment CLI."""

import argparse
import json
import sys
from pathlib import Path

from agent_lab.experiments import canonical, compare, summarize, validate_result


def main():
    parser = argparse.ArgumentParser(prog="agent-lab")
    parser.add_argument("command", choices=["validate", "compare", "summarize"])
    parser.add_argument("files", nargs="+", type=Path)
    args = parser.parse_args()
    try:
        values = [json.loads(path.read_text()) for path in args.files]
        if args.command == "validate":
            for value in values:
                validate_result(value)
            result = {"valid": True, "count": len(values)}
        elif args.command == "compare":
            if len(values) != 2:
                raise ValueError("compare requires exactly two results")
            result = compare(*values)
        else:
            result = summarize(values)
        print(canonical(result))
    except (ValueError, OSError) as error:
        print(str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

agent_lab/archive.py:
"""Immutable lineages, rejected evidence and stratified Pareto selection."""

import json
import re
from collections import defaultdict
from dataclasses import asdict
from pathlib import Path

from agent_lab.benchmarks import benchmark
from agent_lab.experiments import digest, validate_result
from agent_lab.improvement import decide
from agent_lab.runtime import AgentConfig
from agent_lab.trace import atomic_json


def evaluation_identity(results):
    return digest(
        sorted(
            (
                {
                    "task": r["task"],
                    "protocol": r["protocol"],
                    "hardware": r["hardware"],
                    "software": r["software"],
                }
                for r in results
            ),
            key=digest,
        )
    )


def objectives(results):
    groups = defaultdict(list)
    for result in results:
        validate_result(result)
        groups[(result["protocol"]["split"], result["task"]["id"])].append(result)
    scores = [
        [r["correctness"]["score"] for r in groups[key]] for key in sorted(groups)
    ]
    costs = {
        key: [r[group][key] for r in results]
        for key, group in (
            ("generated_tokens", "work"),
            ("wall_seconds", "measurements"),
            ("peak_ram_bytes", "measurements"),
            ("peak_vram_bytes", "measurements"),
        )
    }
    if any(None in values for values in [*scores, *costs.values()]):
        return None
    return [
        *[sum(values) / len(values) for values in scores],
        -sum(costs["generated_tokens"]),
        -sum(costs["wall_seconds"]),
        -max(costs["peak_ram_bytes"]),
        -max(costs["peak_vram_bytes"]),
    ]


class Archive:
    """Single-writer archive; no rejected evidence or ancestry is overwritten."""

    def __init__(self, root):
        self.root = Path(root)

    def entries(self):
        return sorted(p.stem for p in (self.root / "entries").glob("*.json"))

    def read(self, identifier):
        if not re.fullmatch(r"[a-f0-9]{64}", identifier):
            raise ValueError("Invalid archive identity")
        value = json.loads((self.root / "entries" / f"{identifier}.json").read_text())
        if digest(value) != identifier:
            raise ValueError("Archive evidence drift")
        return value

    def add(self, config, results, *, parents=(), mutation):
        if not results or not mutation or len(mutation) > 1280:
            raise ValueError("Archive requires bounded mutation and evidence")
        expected = {
            k: v
            for k, v in asdict(config).items()
            if k not in ("seed", "max_steps", "max_tool_calls")
        }
        for result in results:
            validate_result(result)
            actual = {
                k: v
                for k, v in result["configuration"].items()
                if k not in ("seed", "max_steps", "max_tool_calls")
            }
            if actual != expected:
                raise ValueError("Evidence configuration differs from candidate")
            for budget in ("max_steps", "max_tool_calls"):
                if result["configuration"][budget] > getattr(config, budget):
                    raise ValueError("Evidence exceeds candidate budget")
        parent_records = [self.read(parent) for parent in parents]
        if parent_records:
            decision = decide(parent_records[0]["results"], results)
        else:
            if {r["protocol"]["split"] for r in results} != {"development", "held-out"}:
                raise ValueError("Root requires development and held-out evidence")
            decision = {"status": "baseline"}
        value = {
            "schema_version": 1,
            "configuration": asdict(config),
            "parents": list(parents),
            "mutation": mutation,
            "decision": decision,
            "results": results,
            "evaluation_id": evaluation_identity(results),
            "ordinal": len(self.entries()) + 1,
        }
        identifier = digest(value)
        atomic_json(self.root / "entries" / f"{identifier}.json", value)
        return identifier

    def _regressions(self):
        records = []
        for path in (self.root / "regressions").glob("*.json"):
            value = json.loads(path.read_text())
            if digest(value) != path.stem:
                raise ValueError("Regression evidence drift")
            records.append(value)
        return records

    def regression_due(self, *, interval=3):
        if type(interval) is not int or interval < 1:
            raise ValueError("Regression interval must be positive")
        path = self.root / "cycle.json"
        checked = 0
        if path.exists():
            value = json.loads(path.read_text())
            expected = value.pop("sha256")
            if digest(value) != expected:
                raise ValueError("Regression cycle drift")
            checked = value["archive_ordinal"]
        return len(self.entries()) - checked >= interval

    def record_regression(self, identifier, results, *, suite_id):
        entry = self.read(identifier)
        for result in results:
            validate_result(result)
            config = {k: v for k, v in result["configuration"].items() if k != "seed"}
            expected = {k: v for k, v in entry["configuration"].items() if k != "seed"}
            if config != expected:
                raise ValueError("Regression configuration drift")
        value = {
            "schema_version": 1,
            "candidate": identifier,
            "suite_id": suite_id,
            "results": results,
            "archive_ordinal": len(self.entries()),
            "passed": bool(results)
            and all(r["correctness"]["status"] == "pass" for r in results),
        }
        atomic_json(self.root / "regressions" / f"{digest(value)}.json", value)
        return value

    def frontier(self):
        groups = defaultdict(list)
        regressions = self._regressions()
        failed = {r["candidate"] for r in regressions if not r["passed"]}
        for identifier in self.entries():
            entry = self.read(identifier)
            groups[entry["evaluation_id"]].append((identifier, entry))
        reports = []
        for key, entries in groups.items():
            eligible, excluded = {}, {}
            for identifier, entry in entries:
                point = objectives(entry["results"])
                if entry["decision"]["status"] == "reject" or identifier in failed:
                    excluded[identifier] = "rejected or broader regression failed"
                elif point is None:
                    excluded[identifier] = "unknown correctness or objective"
                else:
                    eligible[identifier] = point
            survivors = [
                identifier
                for identifier, point in eligible.items()
                if not any(
                    all(a >= b for a, b in zip(other, point, strict=True))
                    and other != point
                    for other in eligible.values()
                )
            ]
            reports.append(
                {"evaluation_id": key, "entries": survivors, "excluded": excluded}
            )
        return reports

    async def evaluate_survivors(
        self,
        adapter_factory,
        tasks,
        *,
        output_root,
        interval=3,
        hardware=None,
        software=None,
    ):
        if not self.regression_due(interval=interval):
            return []
        reports = []
        for group in self.frontier():
            for identifier in group["entries"]:
                config = AgentConfig(**self.read(identifier)["configuration"])
                results = [
                    await benchmark(
                        task,
                        adapter_factory(config, task),
                        config,
                        output_root=output_root,
                        hardware=hardware,
                        software=software,
                    )
                    for task in tasks
                ]
                reports.append(
                    self.record_regression(identifier, results, suite_id=digest(tasks))
                )
        cycle = {
            "archive_ordinal": len(self.entries()),
            "suite_id": digest(tasks),
            "regressions": [digest(report) for report in reports],
        }
        atomic_json(self.root / "cycle.json", {**cycle, "sha256": digest(cycle)})
        return reports


def import_improvement(root, bundle):
    """Retain measured rejected lineages without copying their trace artifacts."""
    archive = Archive(root)
    bundle = Path(bundle)
    results = [
        json.loads(line) for line in (bundle / "results.jsonl").read_text().splitlines()
    ]
    manifest = json.loads((bundle / "manifest.json").read_text())
    if digest(results) != manifest["results_sha256"]:
        raise ValueError("Improvement bundle drift")
    midpoint = len(results) // 2
    baseline, candidate = results[:midpoint], results[midpoint:]
    if decide(baseline, candidate) != json.loads(
        (bundle / "decision.json").read_text()
    ):
        raise ValueError("Improvement decision drift")
    root_id = archive.add(
        AgentConfig(**baseline[0]["configuration"]),
        baseline,
        mutation="measured baseline",
    )
    proposal = json.loads((bundle / "proposal.json").read_text())
    child = archive.add(
        AgentConfig(**proposal["configuration"]),
        candidate,
        parents=[root_id],
        mutation=proposal["mutation"]["reason"],
    )
    report = {
        "schema_version": 1,
        "root": root_id,
        "candidate": child,
        "frontier": archive.frontier(),
        "source_bundle_sha256": digest(manifest),
    }
    atomic_json(Path(root) / "report.json", report)
    return report


def main():
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--archive", type=Path, required=True)
    parser.add_argument("--import-improvement", type=Path)
    args = parser.parse_args()
    from agent_lab.experiments import canonical

    print(
        canonical(
            import_improvement(args.archive, args.import_improvement)
            if args.import_improvement
            else Archive(args.archive).frontier()
        )
    )


if __name__ == "__main__":
    main()

agent_lab/backends.py:
"""Local Ollama transport; no inference policy lives in the runtime."""

import asyncio
import json
import urllib.error
import urllib.request
from dataclasses import replace
from urllib.parse import urlparse

from agent_lab.experiments import canonical
from agent_lab.runtime import (
    Reply,
    ResponseFailure,
    RuntimeFailure,
    TransientModelError,
)

RESPONSE_SCHEMA = {
    "type": "object",
    "properties": {
        "content": {"type": "string"},
        "calls": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "name": {"type": "string"},
                    "arguments": {"type": "object"},
                },
                "required": ["name", "arguments"],
            },
        },
    },
    "required": ["content", "calls"],
}


class OllamaAdapter:
    def __init__(self, endpoint="http://127.0.0.1:11434", *, response_schema=None):
        parsed = urlparse(endpoint)
        if parsed.scheme != "http" or parsed.hostname not in (
            "127.0.0.1",
            "localhost",
            "::1",
        ):
            raise ValueError("Ollama endpoint must be loopback HTTP")
        self.endpoint = endpoint.rstrip("/")
        self.response_schema = response_schema or RESPONSE_SCHEMA

    def optimize(self, config, requested):
        report = {}
        for name, value in requested.items():
            if name in ("context_size", "gpu_layers"):
                minimum = 1 if name == "context_size" else 0
                if type(value) is not int or not minimum <= value <= 131072:
                    raise ValueError("Invalid optimization bound")
                config = (
                    replace(config, context_size=value)
                    if name == "context_size"
                    else replace(config, options={**config.options, "num_gpu": value})
                )
                report[name] = {"status": "applied", "value": value}
            else:
                report[name] = {
                    "status": "unavailable",
                    "reason": "no measured control for pinned backend/model",
                }
        return config, report

    @staticmethod
    def _message(message):
        if message["role"] == "tool":
            return {
                "role": "user",
                "content": "Tool "
                + message["name"]
                + " returned: "
                + canonical(message["content"])
                + ". Continue with a JSON reply.",
            }
        if message.get("calls"):
            return {
                "role": message["role"],
                "content": canonical(
                    {"content": message["content"], "calls": message["calls"]}
                ),
            }
        return {"role": message["role"], "content": message["content"]}

    def _request(self, messages, config):
        options = {
            **config.options,
            "seed": config.seed,
            "temperature": config.temperature,
            "num_ctx": config.context_size,
            "num_predict": config.max_output_tokens,
        }
        body = {
            "model": config.model,
            "stream": False,
            "format": self.response_schema,
            "options": options,
            "messages": [self._message(message) for message in messages],
        }
        request = urllib.request.Request(
            self.endpoint + "/api/chat",
            data=json.dumps(body).encode(),
            headers={"Content-Type": "application/json"},
        )
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        try:
            with opener.open(request, timeout=config.request_timeout) as response:
                value = json.load(response)
        except urllib.error.HTTPError as error:
            if error.code in (429, 503):
                raise TransientModelError(f"Backend HTTP {error.code}") from error
            raise RuntimeFailure(f"Backend HTTP {error.code}") from error
        except (urllib.error.URLError, TimeoutError) as error:
            raise RuntimeFailure(
                "Backend transport failed; completion unknown"
            ) from error
        usage = {
            "model_calls": 1,
            "input_tokens": value.get("prompt_eval_count"),
            "output_tokens": value.get("eval_count"),
            "measurements": {
                key: value[key] / 1e9
                for key in ("load_duration", "prompt_eval_duration", "eval_duration")
                if key in value
            },
        }
        try:
            parsed = json.loads(value["message"]["content"])
            if not isinstance(parsed, dict):
                raise RuntimeFailure("Backend reply must be an object")
            parsed.update(usage)
            return Reply.parse(parsed)
        except (KeyError, ValueError, TypeError, RuntimeFailure) as error:
            raise ResponseFailure("Malformed backend response", **usage) from error

    async def complete(self, messages, config):
        # Socket work is finite. Cancellation discards the result; no tool executes.
        return await asyncio.to_thread(self._request, messages, config)

agent_lab/baselines.py:
"""Pinned local-model baseline acquisition, measurement and immutable evidence."""

import argparse
import asyncio
import json
import re
import sys
import time
import urllib.request
from dataclasses import asdict, replace
from pathlib import Path

from agent_lab.backends import OllamaAdapter
from agent_lab.benchmarks import benchmark, discover
from agent_lab.experiments import canonical, digest, summarize, validate_result
from agent_lab.runtime import AgentConfig
from agent_lab.telemetry import hardware_profile, software_identity
from agent_lab.trace import atomic_json


def inventory():
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    values = []
    for name in ("tags", "version"):
        with opener.open(f"http://127.0.0.1:11434/api/{name}", timeout=15) as response:
            values.append(json.load(response))
    return values[0], values[1]["version"]


def validate_manifest(config, tags, backend_version):
    model = next(
        (item for item in tags["models"] if item["name"] == config["model"]), None
    )
    if model is None or model["digest"] != config["model_digest"]:
        raise ValueError("Pinned model unavailable or changed")
    if backend_version != config["backend_version"]:
        raise ValueError("Backend version drift")
    if model["details"]["quantization_level"] != config["quantization"]:
        raise ValueError("Quantization drift")


def baseline_report(runs):
    groups = {}
    for run in runs:
        validate_result(run)
        config = run["configuration"]
        if (
            config.get("backend") != "ollama"
            or not re.fullmatch(r"[a-f0-9]{64}", config.get("model_digest", ""))
            or not config.get("quantization")
        ):
            raise ValueError(
                "Real baselines require pinned model identity and quantization"
            )
        family = {key: value for key, value in config.items() if key != "seed"}
        key = digest(
            {
                "configuration": family,
                "task": run["task"],
                "hardware": run["hardware"],
                "software": run["software"],
                "split": run["protocol"]["split"],
            }
        )
        groups.setdefault(key, []).append(run)
    report = []
    for key, samples in sorted(groups.items()):
        if len(samples) < 5:
            raise ValueError("Baseline requires at least five samples per stratum")
        report.append(
            {
                "identity": key,
                "task": samples[0]["task"],
                "configuration": {
                    k: v for k, v in samples[0]["configuration"].items() if k != "seed"
                },
                "hardware": samples[0]["hardware"],
                "software": samples[0]["software"],
                "samples": len(samples),
                "passed": sum(r["correctness"]["status"] == "pass" for r in samples),
                "failed": sum(r["correctness"]["status"] == "fail" for r in samples),
                "errors": sum(r["correctness"]["status"] == "error" for r in samples),
                "summary": summarize(samples),
            }
        )
    return report


def capture():
    tags, version = inventory()
    profiles = {}
    for label, name, gpu in (
        ("small-q4-cpu", "qwen2.5-coder:0.5b-instruct-q4_K_M", 0),
        ("small-q4-gpu", "qwen2.5-coder:0.5b-instruct-q4_K_M", 99),
        ("small-q8-gpu", "qwen2.5-coder:0.5b-instruct-q8_0", 99),
        ("medium-q4-gpu", "qwen2.5-coder:7b", 99),
    ):
        model = next((m for m in tags["models"] if m["name"] == name), None)
        if model is None:
            raise ValueError(f"Acquire declared model first: {name}")
        profiles[label] = asdict(
            AgentConfig(
                model=name,
                model_digest=model["digest"],
                backend="ollama",
                backend_version=version,
                quantization=model["details"]["quantization_level"],
                options={"num_gpu": gpu},
            )
        )
    return {"schema_version": 1, "hardware": hardware_profile(), "profiles": profiles}


def unload(model):
    body = json.dumps({"model": model, "keep_alive": 0}).encode()
    request = urllib.request.Request(
        "http://127.0.0.1:11434/api/generate",
        data=body,
        headers={"Content-Type": "application/json"},
    )
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open(request, timeout=30) as response:
        json.load(response)


def unload_experiment_models(allowed):
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open("http://127.0.0.1:11434/api/ps", timeout=15) as response:
        loaded = json.load(response)["models"]
    for model in loaded:
        if model["name"] not in allowed:
            raise ValueError("Unrelated model loaded; use a dedicated idle backend")
    for model in loaded:
        unload(model["name"])
    deadline = time.perf_counter() + 10
    while True:
        with opener.open("http://127.0.0.1:11434/api/ps", timeout=15) as response:
            remaining = json.load(response)["models"]
        if not remaining:
            return
        if time.perf_counter() >= deadline:
            raise ValueError("Backend did not unload; baseline isolation unavailable")
        time.sleep(0.2)


async def run_baselines(
    manifest, output, *, repeats=5, split="development", task_ids=None
):
    if (
        manifest.get("schema_version") != 1
        or not manifest.get("profiles")
        or repeats < 5
    ):
        raise ValueError("Invalid baseline manifest/repeat policy")
    if output.exists():
        raise ValueError("Baseline output must be new; evidence is immutable")
    hardware, software = hardware_profile(), software_identity()
    if hardware != manifest["hardware"]:
        raise ValueError("Hardware differs from declared profile")
    output.mkdir(parents=True)
    results = []
    cold_results = []
    tasks = [task for task in discover(split) if not task_ids or task["id"] in task_ids]
    if not tasks:
        raise ValueError("No matching workloads")
    for label, values in sorted(manifest["profiles"].items()):
        config = AgentConfig(**values)
        validate_manifest(values, *inventory())
        await asyncio.to_thread(
            unload_experiment_models,
            {values["model"] for values in manifest["profiles"].values()},
        )
        cold = await benchmark(
            tasks[0],
            OllamaAdapter(),
            replace(config, seed=99),
            repeat=repeats,
            hardware=hardware,
            software=software,
            output_root=output / "runs",
        )
        cold_results.append(cold)
        print(
            canonical(
                {
                    "profile": label,
                    "phase": "cold-load",
                    "status": cold["correctness"]["status"],
                }
            ),
            flush=True,
        )
        for task in tasks:
            for repeat in range(repeats):
                sample = await benchmark(
                    task,
                    OllamaAdapter(),
                    replace(config, seed=repeat),
                    repeat=repeat,
                    hardware=hardware,
                    software=software,
                    output_root=output / "runs",
                )
                results.append(sample)
                print(
                    canonical(
                        {
                            "profile": label,
                            "task": task["id"],
                            "repeat": repeat,
                            "status": sample["correctness"]["status"],
                        }
                    ),
                    flush=True,
                )
        validate_manifest(values, *inventory())
    text = "".join(canonical(result) + "\n" for result in results)
    (output / "results.jsonl").write_text(text)
    (output / "cold-results.jsonl").write_text(
        "".join(canonical(result) + "\n" for result in cold_results)
    )
    atomic_json(output / "summary.json", baseline_report(results))
    atomic_json(
        output / "manifest.json",
        {
            "schema_version": 1,
            "input": manifest,
            "results_sha256": digest(results),
            "cold_results_sha256": digest(cold_results),
            "software": software,
            "repeats": repeats,
            "tasks": [
                {"id": task["id"], "fixture_hash": digest(task)} for task in tasks
            ],
            "conventions_source_revision": "e6acb5310afaf15c0cba24f87108f5f4ad1bedc3",
        },
    )
    return results


def verify_bundle(output):
    manifest = json.loads((output / "manifest.json").read_text())
    results = [
        json.loads(line) for line in (output / "results.jsonl").read_text().splitlines()
    ]
    if digest(results) != manifest["results_sha256"]:
        raise ValueError("Baseline evidence drift")
    cold = [
        json.loads(line)
        for line in (output / "cold-results.jsonl").read_text().splitlines()
    ]
    for run in cold:
        validate_result(run)
    if digest(cold) != manifest["cold_results_sha256"]:
        raise ValueError("Cold-load evidence drift")
    if len(cold) != len(manifest["input"]["profiles"]):
        raise ValueError("Incomplete cold-load evidence")
    expected_count = (
        len(manifest["input"]["profiles"])
        * len(manifest["tasks"])
        * manifest["repeats"]
    )
    if len(results) != expected_count:
        raise ValueError("Incomplete baseline evidence")
    if baseline_report(results) != json.loads((output / "summary.json").read_text()):
        raise ValueError("Baseline summary drift")
    return {"valid": True, "samples": len(results)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["capture", "run", "verify"])
    parser.add_argument("--manifest", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--repeats", type=int, default=5)
    parser.add_argument("--task", action="append")
    args = parser.parse_args()
    try:
        if args.command == "capture":
            if args.output.exists():
                raise ValueError("Choose a new manifest path for explicit recapture")
            atomic_json(args.output, capture())
        elif args.command == "verify":
            print(canonical(verify_bundle(args.output)))
        else:
            if args.manifest is None:
                raise ValueError("run requires --manifest")
            asyncio.run(
                run_baselines(
                    json.loads(args.manifest.read_text()),
                    args.output,
                    repeats=args.repeats,
                    task_ids=args.task,
                )
            )
    except (ValueError, OSError, TypeError) as error:
        print(str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

