"""Schema-checked reusable utilities with identity, provenance and transparent cache."""

import argparse
import copy
import inspect
import json
import sys
from dataclasses import asdict
from pathlib import Path

from jsonschema import Draft202012Validator

from agent_lab.experiments import ROOT, canonical, digest
from agent_lab.runtime import RuntimeFailure
from agent_lab.trace import atomic_json


def batch_sum(value):
    return str(sum(sum(batch) for batch in value["batches"]))


IMPLEMENTATIONS = {"batch_sum": batch_sum}


class Capability:
    def __init__(self, manifest):
        if (
            manifest.get("schema_version") != 1
            or manifest.get("implementation") not in IMPLEMENTATIONS
        ):
            raise ValueError("Unsupported capability manifest")
        self.manifest = copy.deepcopy(manifest)
        self.id = manifest["id"]
        self.function = IMPLEMENTATIONS[manifest["implementation"]]
        self.identity = digest(
            {
                "manifest": manifest,
                "implementation_source": inspect.getsource(self.function),
            }
        )
        for name in ("input_schema", "output_schema"):
            Draft202012Validator.check_schema(manifest[name])

    def _validate(self, name, value):
        errors = list(Draft202012Validator(self.manifest[name]).iter_errors(value))
        if errors:
            raise ValueError("Invalid capability " + name + ": " + errors[0].message)

    def invoke(self, inputs, *, cache=None, source_runs=()):
        self._validate("input_schema", inputs)
        input_hash = digest(inputs)
        key = digest({"capability": self.identity, "input_hash": input_hash})
        path = Path(cache) / (key + ".json") if cache is not None else None
        if path is not None and path.exists():
            try:
                record = json.loads(path.read_text())
                if not isinstance(record, dict):
                    raise ValueError("Invalid disposable cache record")
                self._validate("output_schema", record["output"])
                if (
                    record["capability_hash"] == self.identity
                    and record["input_hash"] == input_hash
                    and digest(record["output"]) == record["output_hash"]
                    and digest({k: v for k, v in record.items() if k != "record_hash"})
                    == record["record_hash"]
                ):
                    return {**record, "cached": True}
            except ValueError, KeyError:
                pass  # Invalid disposable cache is recomputed, never used as evidence.
        output = self.function(copy.deepcopy(inputs))
        self._validate("output_schema", output)
        record = {
            "schema_version": 1,
            "capability_id": self.id,
            "capability_hash": self.identity,
            "input_hash": input_hash,
            "output": output,
            "output_hash": digest(output),
            "source_runs": sorted(set(source_runs)),
            "cached": False,
        }
        record["record_hash"] = digest(record)
        if path is not None:
            atomic_json(path, record)
        return record


def discover_capabilities():
    return [
        Capability(json.loads(path.read_text()))
        for path in sorted((ROOT / "capabilities").glob("*.json"))
    ]


class CapabilityRunner:
    """A trusted execution strategy; this utility never calls a model adapter."""

    def __init__(self, capability, inputs, *, cache=None, source_runs=()):
        self.capability, self.inputs = capability, copy.deepcopy(inputs)
        self.cache, self.source_runs = cache, source_runs

    async def __call__(self, adapter, tools, config, state, emit):
        if (
            config.backend != "capability"
            or config.options.get("capability") != self.capability.id
            or config.model_digest != self.capability.identity
            or config.max_tool_calls < 1
        ):
            raise RuntimeFailure("Capability identity/budget mismatch")
        state.status = "running"
        emit("state", {"status": state.status, "configuration": asdict(config)})
        emit(
            "tool_request",
            {
                "name": self.capability.id,
                "arguments": self.inputs,
                "capability_hash": self.capability.identity,
            },
        )
        result = self.capability.invoke(
            self.inputs, cache=self.cache, source_runs=self.source_runs
        )
        state.tool_calls += 1
        state.steps += 1
        state.output = result["output"]
        state.status = "completed"
        emit(
            "tool_result",
            {
                "name": self.capability.id,
                "value": state.output,
                "provenance": {k: v for k, v in result.items() if k != "output"},
            },
        )
        emit("state", {"status": state.status})
        return state


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["list", "run"])
    parser.add_argument("--id")
    parser.add_argument("--input", type=Path)
    parser.add_argument("--cache", type=Path)
    args = parser.parse_args()
    try:
        capabilities = discover_capabilities()
        if args.command == "list":
            print(
                canonical(
                    [
                        {
                            "id": c.id,
                            "version": c.manifest["version"],
                            "kind": c.manifest["kind"],
                            "hash": c.identity,
                        }
                        for c in capabilities
                    ]
                )
            )
        else:
            capability = next((c for c in capabilities if c.id == args.id), None)
            if capability is None or args.input is None:
                raise ValueError("run requires a known --id and --input JSON file")
            print(
                canonical(
                    capability.invoke(
                        json.loads(args.input.read_text()), cache=args.cache
                    )
                )
            )
    except (ValueError, OSError) as error:
        print(str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

agent_lab/context.py:
"""Incrementally retained task state and explicit model context projections."""

import copy

from agent_lab.experiments import canonical


def project_context(state, policy):
    if policy in ("full", "relevance"):
        return copy.deepcopy(state.messages)
    if policy != "retained":
        raise ValueError("Unknown context policy")
    completed = [
        [entry["name"], entry["arguments"], entry["result"]]
        for entry in state.working_memory
    ]
    return [
        copy.deepcopy(state.messages[0]),
        {
            "role": "user",
            "content": "Completed tools (name, args, result). No repeats.\n"
            + canonical({"completed": completed}),
        },
    ]


def select_input(task, policy):
    value = copy.deepcopy(task["input"])
    if policy == "relevance" and task["category"] == "retrieval":
        value["facts"] = {value["key"]: value["facts"][value["key"]]}
    return value

agent_lab/distillation.py:
"""Derive trusted reusable artifacts from independently rechecked experience."""

import hashlib
import json
from pathlib import Path

from agent_lab.benchmarks import load_task
from agent_lab.capabilities import CapabilityRunner, discover_capabilities
from agent_lab.evaluators import independent_evaluate
from agent_lab.experiments import ROOT, digest, validate_result
from agent_lab.trace import load_trace


def _source(path, source_root):
    root, path = Path(source_root).resolve(), Path(path).resolve()
    if not path.is_relative_to(root):
        raise ValueError("Source outside declared evidence root")
    result = validate_result(json.loads((path / "result.json").read_text()))
    if (
        result["protocol"]["split"] != "development"
        or result["task"]["id"] != "batch-sum"
        or result["correctness"]["status"] != "pass"
    ):
        raise ValueError(
            "Distillation requires successful development batch experience"
        )
    if (
        result["configuration"]["backend"] == "fixture"
        or not result["work"]["generated_tokens"]
        or not result["work"]["model_calls"]
    ):
        raise ValueError("Source must be measured model experience")
    trace = load_trace(path / "trace.json", artifact_root=path)
    if (
        trace["run_id"] != result["run_id"]
        or trace["configuration_id"] != digest(result["configuration"])
        or trace["artifacts"] != result["artifacts"]
    ):
        raise ValueError("Source trace identity drift")
    task = load_task("development", "batch-sum")
    output = json.loads((path / "output.json").read_text())["content"]
    if (
        result["task"]["fixture_hash"] != digest(task)
        or independent_evaluate(task, output)["status"] != "pass"
    ):
        raise ValueError("Source no longer independently verifies")
    proof = {
        "run_id": result["run_id"],
        "path": path.relative_to(root).as_posix(),
        "result_sha256": hashlib.sha256(
            (path / "result.json").read_bytes()
        ).hexdigest(),
        "trace_sha256": hashlib.sha256((path / "trace.json").read_bytes()).hexdigest(),
        "fixture_sha256": digest(task),
        "output_sha256": digest(output),
        "configuration": result["configuration"],
    }
    return proof, {
        "input": task["input"],
        "output": output,
        "source_run_id": result["run_id"],
    }


def distill(sources, *, source_root=ROOT):
    if not sources or len(sources) > 32:
        raise ValueError("Select 1..32 verified source runs")
    records = [_source(path, source_root) for path in sorted(sources)]
    proofs, examples = zip(*records, strict=True)
    if len({p["run_id"] for p in proofs}) != len(proofs):
        raise ValueError("Duplicate source experience")
    capability = next(c for c in discover_capabilities() if c.id == "batch-sum-v1")
    for example in examples:
        if capability.invoke(example["input"])["output"] != example["output"]:
            raise ValueError("Distilled procedure differs from verified experience")
    artifact = {
        "schema_version": 1,
        "kind": "deterministic-tool-and-verified-examples",
        "recipe": "batch-sum-experience-v1",
        "capability_id": capability.id,
        "capability_sha256": capability.identity,
        "provenance": list(proofs),
        "examples": list(examples),
        "input_schema": capability.manifest["input_schema"],
        "procedure": "Sum integer batches, total them, return decimal text.",
    }
    return {**artifact, "artifact_sha256": digest(artifact)}


def verify_artifact(artifact, *, source_root=ROOT):
    body = {k: v for k, v in artifact.items() if k != "artifact_sha256"}
    if digest(body) != artifact["artifact_sha256"]:
        raise ValueError("Distilled artifact drift")
    paths = [(Path(source_root) / p["path"]).resolve() for p in artifact["provenance"]]
    rebuilt = distill(paths, source_root=source_root)
    if rebuilt != artifact:
        raise ValueError("Distilled provenance or implementation drift")
    return next(c for c in discover_capabilities() if c.id == artifact["capability_id"])


class DistilledRunner(CapabilityRunner):
    def __init__(self, artifact, inputs, *, source_root=ROOT, cache=None):
        self.artifact = artifact
        super().__init__(
            verify_artifact(artifact, source_root=source_root),
            inputs,
            cache=cache,
            source_runs=[p["run_id"] for p in artifact["provenance"]],
        )

    async def __call__(self, adapter, tools, config, state, emit):
        if config.options.get("distilled_artifact") != self.artifact["artifact_sha256"]:
            raise ValueError("Distilled execution identity drift")
        emit(
            "authority",
            {
                "scope": "verified-distilled-tool",
                "artifact_sha256": self.artifact["artifact_sha256"],
            },
        )
        return await super().__call__(adapter, tools, config, state, emit)

agent_lab/evaluator_worker.py:
"""Isolated stdlib-only evaluator entry point; never executes candidate code."""

import hashlib
import json
import sys
from pathlib import Path


def main():
    path = Path(sys.argv[1]).resolve()
    root = Path(__file__).resolve().parents[1] / "benchmarks"
    if not path.is_relative_to(root):
        raise ValueError("Evaluator task outside authority")
    task = json.loads(path.read_text())
    encoded = json.dumps(task, sort_keys=True, separators=(",", ":"), allow_nan=False)
    if hashlib.sha256(encoded.encode()).hexdigest() != sys.argv[2]:
        raise ValueError("Evaluator fixture drift")
    candidate = json.load(sys.stdin)
    if not isinstance(candidate, dict) or not isinstance(candidate.get("output"), str):
        raise ValueError("Invalid candidate output")
    passed = candidate["output"] == task["expected"]
    print(
        json.dumps(
            {
                "status": "pass" if passed else "fail",
                "score": int(passed),
                "evaluator": task["evaluator"],
            },
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()

agent_lab/experiments.py:
"""Versioned experiment validation and capability/resource comparisons."""

import hashlib
import json
import statistics
from pathlib import Path

from jsonschema import Draft202012Validator

ROOT = Path(__file__).resolve().parents[1]
MEASUREMENTS = (
    "wall_seconds",
    "inference_seconds",
    "tool_seconds",
    "setup_seconds",
    "cpu_seconds",
    "gpu_seconds",
    "peak_ram_bytes",
    "peak_vram_bytes",
    "cpu_utilization",
    "gpu_utilization",
    "energy_joules",
)
WORK = (
    "input_tokens",
    "output_tokens",
    "generated_tokens",
    "model_calls",
    "retries",
    "tool_calls",
)


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def validate_result(value):
    schema = json.loads((ROOT / "schemas/result-v1.json").read_text())
    errors = sorted(Draft202012Validator(schema).iter_errors(value), key=str)
    if errors:
        raise ValueError("; ".join(error.message for error in errors))
    canonical(value)  # Reject non-finite numbers even when the validator accepts them.
    status = value["correctness"]["status"]
    score = value["correctness"]["score"]
    if status == "pass" and score != 1:
        raise ValueError("A passing result requires full credit")
    if status == "fail" and (score is None or score == 1):
        raise ValueError("A failed result requires less than full credit")
    if status in ("error", "cancelled", "unavailable") and score is not None:
        raise ValueError("Unevaluated results cannot claim correctness")
    for name, measurement in value["measurements"].items():
        if measurement is not None and not value["measurement_sources"].get(name):
            raise ValueError(f"Measurement source required: {name}")
    return value


def compare(baseline, candidate):
    for value in (baseline, candidate):
        validate_result(value)
    for field in ("task", "protocol", "hardware", "software"):
        if baseline[field] != candidate[field]:
            raise ValueError(f"Incompatible {field}; stratify before comparing")
    changes = sorted(
        key
        for key in baseline["configuration"].keys() | candidate["configuration"].keys()
        if baseline["configuration"].get(key) != candidate["configuration"].get(key)
    )
    result = {"configuration_changes": changes}
    for metric, group in (
        ("generated_tokens", "work"),
        ("wall_seconds", "measurements"),
        ("peak_ram_bytes", "measurements"),
    ):
        costs = baseline[group][metric], candidate[group][metric]
        scores = baseline["correctness"]["score"], candidate["correctness"]["score"]
        if None in costs or None in scores:
            outcome = "unavailable"
        elif (
            scores[1] >= scores[0]
            and costs[1] <= costs[0]
            and (scores[1] > scores[0] or costs[1] < costs[0])
        ):
            outcome = "candidate_dominates"
        elif (
            scores[0] >= scores[1]
            and costs[0] <= costs[1]
            and (scores[0] > scores[1] or costs[0] < costs[1])
        ):
            outcome = "baseline_dominates"
        elif scores[0] == scores[1] and costs[0] == costs[1]:
            outcome = "equivalent"
        else:
            outcome = "tradeoff"
        result[metric] = outcome
    return result


def summarize(runs):
    if not runs:
        raise ValueError("At least one sample required")
    repeats = set()
    for run in runs:
        validate_result(run)
        for key in ("task", "hardware", "software"):
            if run[key] != runs[0][key]:
                raise ValueError(f"Mixed {key}")
        configuration = {
            key: value for key, value in run["configuration"].items() if key != "seed"
        }
        first_configuration = {
            key: value
            for key, value in runs[0]["configuration"].items()
            if key != "seed"
        }
        if configuration != first_configuration:
            raise ValueError("Mixed configuration")
        protocol = {k: v for k, v in run["protocol"].items() if k != "repeat"}
        first = {k: v for k, v in runs[0]["protocol"].items() if k != "repeat"}
        if protocol != first or run["protocol"]["repeat"] in repeats:
            raise ValueError("Mixed protocol or duplicate repeat")
        repeats.add(run["protocol"]["repeat"])
    result = {"sampling_seeds": [run["configuration"].get("seed") for run in runs]}
    for key in (*WORK, *MEASUREMENTS, "score"):
        group = (
            "work"
            if key in WORK
            else "correctness"
            if key == "score"
            else "measurements"
        )
        values = [run[group][key] for run in runs if run[group][key] is not None]
        result[key] = {
            "samples": len(values),
            "missing": len(runs) - len(values),
            "mean": statistics.mean(values) if values else None,
            "sample_stdev": statistics.stdev(values) if len(values) > 1 else None,
        }
    return result

agent_lab/improvement.py:
"""Bounded self-proposals and independent correctness/compute decisions."""

import copy
from collections import defaultdict
from dataclasses import asdict, replace

from agent_lab.experiments import compare, digest, validate_result
from agent_lab.runtime import AgentState, run
from agent_lab.trace import Trace


def materialize(baseline, proposal):
    if not isinstance(proposal, dict) or set(proposal) != {"changes", "reason"}:
        raise ValueError("Proposal requires changes and reason")
    reason, changes = proposal["reason"], proposal["changes"]
    if (
        not isinstance(reason, str)
        or not 1 <= len(reason) <= 1280
        or not isinstance(changes, dict)
        or not changes
    ):
        raise ValueError("Invalid bounded proposal")
    allowed = {"context_policy", "feedback", "max_retries", "max_output_tokens"}
    if changes.keys() - allowed:
        raise ValueError("Mutation cannot alter evaluation or tool authority")
    if "feedback" in changes and (
        not isinstance(changes["feedback"], str) or len(changes["feedback"]) > 1280
    ):
        raise ValueError("Instruction mutation too large")
    for name, bounds in {"max_retries": (0, 3), "max_output_tokens": (16, 512)}.items():
        if name in changes and (
            type(changes[name]) is not int
            or not bounds[0] <= changes[name] <= bounds[1]
        ):
            raise ValueError("Mutation exceeds budget bounds")
    return replace(baseline, **changes)


def development_view(results):
    groups = {}
    for result in results:
        validate_result(result)
        if result["protocol"]["split"] != "development":
            raise ValueError("Proposal cannot inspect held-out evidence")
        config = {k: v for k, v in result["configuration"].items() if k != "seed"}
        key = result["task"]["id"], digest(config)
        groups.setdefault(
            key,
            {
                "task": key[0],
                "configuration": config,
                "scores": [],
                "tokens": [],
                "run_ids": [],
            },
        )
        groups[key]["scores"].append(result["correctness"]["score"])
        groups[key]["tokens"].append(result["work"]["generated_tokens"])
        groups[key]["run_ids"].append(result["run_id"])
    return list(groups.values())


async def propose(adapter, baseline, development_results):
    from agent_lab.experiments import canonical

    view = development_view(development_results)
    prompt = (
        "Return a JSON reply with content and calls. Propose one bounded improvement. "
        "Call propose "
        "once with arguments {changes: object, reason: string}. Allowed changes: "
        "context_policy full/retained/relevance, feedback string (1280 chars), "
        "max_retries 0..3, max_output_tokens 16..512. Relevance selects only the "
        "requested fact for retrieval; retained compresses completed tool history. "
        "Use the observed development results, especially retrieval comparisons. "
        "You have no filesystem, fixture or evaluator authority.\n" + canonical(view)
    )
    proposals = []

    def capture(arguments):
        materialize(baseline, arguments)
        if proposals:
            raise ValueError("Only one mutation may be proposed")
        proposals.append(copy.deepcopy(arguments))
        return "proposal recorded; finish with calls: []"

    planner = replace(baseline, max_steps=2, max_tool_calls=1)
    trace = Trace(
        digest({"prompt": prompt, "config": asdict(planner)})[:24],
        "scaffolding-proposal",
        digest(asdict(planner)),
    )
    state = AgentState(prompt)
    error = None
    try:
        await run(
            adapter,
            {"propose": capture},
            planner,
            state,
            trace.emit,
        )
    except Exception as failure:
        error = type(failure).__name__
    return (
        proposals[0] if proposals else None,
        trace,
        {
            "state": state.status,
            "error": error,
            "input_tokens": state.input_tokens,
            "output_tokens": state.output_tokens,
            "model_calls": state.model_calls,
            "development_evidence_sha256": digest(view),
            "observed_final_content": state.output,
        },
    )


def _cohorts(results):
    groups = defaultdict(list)
    identities = set()
    for result in results:
        validate_result(result)
        key = result["protocol"]["split"], result["task"]["id"]
        identity = (*key, result["protocol"]["repeat"])
        if identity in identities:
            raise ValueError("Duplicate cohort sample")
        identities.add(identity)
        groups[key].append(result)
    return groups


def decide(baseline, candidate):
    before, after = _cohorts(baseline), _cohorts(candidate)
    if before.keys() != after.keys() or not {"development", "held-out"}.issubset(
        {k[0] for k in before}
    ):
        raise ValueError("Decision requires matching development and held-out cohorts")
    comparisons, regression, improvement, unknown = [], [], False, False
    for key, initial in before.items():
        changed = after[key]
        if len(initial) != len(changed):
            raise ValueError("Cohort sample counts differ")
        initial = sorted(initial, key=lambda r: r["protocol"]["repeat"])
        changed = sorted(changed, key=lambda r: r["protocol"]["repeat"])
        for a, b in zip(initial, changed, strict=True):
            comparisons.append(compare(a, b))
        a_scores, b_scores = (
            [r["correctness"]["score"] for r in initial],
            [r["correctness"]["score"] for r in changed],
        )
        if None in a_scores or None in b_scores:
            unknown = True
            continue
        if sum(b_scores) < sum(a_scores):
            regression.append(list(key))
        if key[0] == "development" and sum(b_scores) > sum(a_scores):
            improvement = True
    a_tokens = [r["work"]["generated_tokens"] for r in baseline]
    b_tokens = [r["work"]["generated_tokens"] for r in candidate]
    token_improvement = (
        None not in a_tokens and None not in b_tokens and sum(b_tokens) < sum(a_tokens)
    )
    status = (
        "reject"
        if regression or unknown
        else "accept"
        if improvement or token_improvement
        else "archive"
    )
    return {
        "status": status,
        "correctness_regressions": regression,
        "unknown_correctness": unknown,
        "development_improvement": improvement,
        "total_token_improvement": token_improvement,
        "comparisons": comparisons,
        "baseline_sha256": digest(baseline),
        "candidate_sha256": digest(candidate),
    }

agent_lab/inference_experiment.py:
"""Measure adapter-level quantization, placement and context choices."""

import argparse
import asyncio
import json
from dataclasses import replace
from pathlib import Path

from agent_lab.backends import OllamaAdapter
from agent_lab.baselines import inventory, unload_experiment_models, validate_manifest
from agent_lab.benchmarks import benchmark, load_task
from agent_lab.experiments import ROOT, canonical, compare, digest, summarize
from agent_lab.optimization import negotiate
from agent_lab.runtime import AgentConfig
from agent_lab.telemetry import hardware_profile, software_identity
from agent_lab.trace import atomic_json


async def experiment(output):
    if output.exists():
        raise ValueError("Choose a new evidence directory")
    manifest = json.loads((ROOT / "configurations/local-baselines-v1.json").read_text())
    profiles = {
        label: AgentConfig(**value) for label, value in manifest["profiles"].items()
    }
    profiles["medium-context-2048"], negotiation = negotiate(
        OllamaAdapter(),
        profiles["medium-q4-gpu"],
        {
            "context_size": 2048,
            "prefix_cache": True,
            "kv_reuse": True,
            "speculation": True,
            "batching": True,
        },
    )
    for config in profiles.values():
        from dataclasses import asdict

        validate_manifest(asdict(config), *inventory())
    hardware, software = hardware_profile(), software_identity()
    if hardware != manifest["hardware"]:
        raise ValueError("Hardware drift")
    allowed = {p["model"] for p in manifest["profiles"].values()}
    task = load_task("development", "batch-sum")
    output.mkdir(parents=True)
    groups = {}
    cold = []
    for label, profile in profiles.items():
        await asyncio.to_thread(unload_experiment_models, allowed)
        groups[label] = []
        for repeat in range(6):
            config = replace(profile, seed=repeat)
            adapter = OllamaAdapter()
            result = await benchmark(
                task,
                adapter,
                config,
                repeat=repeat,
                hardware=hardware,
                software=software,
                output_root=output / "runs",
            )
            if repeat == 5:
                groups[label].append(result)
            elif repeat == 0:
                cold.append(result)
            else:
                groups[label].append(result)
            print(
                canonical(
                    {
                        "configuration": label,
                        "repeat": repeat,
                        "status": result["correctness"]["status"],
                    }
                ),
                flush=True,
            )
    # Repeats 1..5 are steady state after separately retained repeat 0.
    report = {
        label: {
            "passed": sum(r["correctness"]["status"] == "pass" for r in results),
            "summary": summarize(results),
        }
        for label, results in groups.items()
    }
    report["negotiation"] = negotiation
    report["comparisons"] = {
        label: [
            compare(a, b) for a, b in zip(groups[reference], groups[label], strict=True)
        ]
        for label, reference in {
            "small-q4-gpu": "small-q4-cpu",
            "small-q8-gpu": "small-q4-gpu",
            "medium-context-2048": "medium-q4-gpu",
        }.items()
    }
    results = [r for group in groups.values() for r in group]
    (output / "results.jsonl").write_text("".join(canonical(r) + "\n" for r in results))
    atomic_json(output / "cold-results.json", cold)
    atomic_json(output / "report.json", report)
    atomic_json(
        output / "manifest.json",
        {
            "schema_version": 1,
            "results_sha256": digest(results),
            "cold_sha256": digest(cold),
        },
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    asyncio.run(experiment(parser.parse_args().output))


if __name__ == "__main__":
    main()

agent_lab/learning.py:
"""Learning entry gate and verified synthetic examples; no ML imports required."""

import copy
import hashlib
import json
import random
from fractions import Fraction

from agent_lab.archive import Archive
from agent_lab.baselines import verify_bundle
from agent_lab.benchmarks import discover, load_task, prompt_for
from agent_lab.distillation import verify_artifact
from agent_lab.evaluators import independent_evaluate
from agent_lab.experiments import ROOT, canonical, digest


def entry_gate():
    baseline = verify_bundle(ROOT / "evidence/baselines/local-v1")
    archive_root = ROOT / "evidence/archive/local-v1"
    report = json.loads((archive_root / "report.json").read_text())
    if (
        Archive(archive_root).read(report["candidate"])["decision"]["status"]
        != "reject"
    ):
        raise ValueError("Regression protection evidence unavailable")
    tasks = [*discover("development"), *discover("held-out")]
    for task in tasks:
        if (
            independent_evaluate(task, task["expected"])["status"] != "pass"
            or independent_evaluate(task, "invalid-gate-output")["status"] != "fail"
        ):
            raise ValueError("Independent evaluator gate failed")
    protected = {
        p.relative_to(ROOT).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest()
        for p in [
            ROOT / "agent_lab/evaluator_worker.py",
            ROOT / "agent_lab/evaluators.py",
            ROOT / "agent_lab/improvement.py",
            ROOT / "agent_lab/archive.py",
        ]
    }
    return {
        "schema_version": 1,
        "passed": True,
        "baseline_samples": baseline["samples"],
        "task_hashes": {t["id"]: digest(t) for t in tasks},
        "protected_sources": protected,
        "held_out_tasks": [t["id"] for t in tasks if t["split"] == "held-out"],
        "held_out_input_hashes": [
            digest(t["input"]) for t in tasks if t["split"] == "held-out"
        ],
    }


def build_data(artifact, *, count=32, seed=17):
    if type(count) is not int or not 1 <= count <= 64:
        raise ValueError("Training data requires 1..64 examples")
    teacher = verify_artifact(artifact)
    template = load_task("development", "sum")
    forbidden = {digest(t["input"]) for t in discover("held-out")}
    randomizer = random.Random(seed)
    examples, seen = [], set()
    for attempt in range(1000):
        numbers = (
            template["input"]["numbers"]
            if attempt == 0
            else [randomizer.randint(-9, 9) for _ in range(3)]
        )
        inputs = {"numbers": numbers}
        if digest(inputs) in seen | forbidden:
            continue
        seen.add(digest(inputs))
        output = teacher.invoke({"batches": [[n] for n in numbers]})["output"]
        if output != str(int(sum((Fraction(n) for n in numbers), Fraction(0)))):
            raise ValueError("Synthetic teacher disagrees with independent arithmetic")
        task = copy.deepcopy(template)
        task["input"] = inputs
        examples.append(
            {
                "input": inputs,
                "prompt": prompt_for(task),
                "response": canonical({"content": output, "calls": []}),
                "source_runs": [p["run_id"] for p in artifact["provenance"]],
            }
        )
        if len(examples) == count:
            break
    if len(examples) != count:
        raise ValueError("Could not generate bounded unique training examples")
    value = {
        "schema_version": 1,
        "recipe": "verified-batch-tool-to-sum-response-v1",
        "seed": seed,
        "source_artifact_sha256": artifact["artifact_sha256"],
        "examples": examples,
    }
    value["data_sha256"] = digest(value)
    validate_data(value, artifact=artifact, held_out_hashes=forbidden)
    return value


def validate_data(data, *, artifact=None, held_out_hashes=()):
    if artifact is None:
        artifact = json.loads(
            (
                ROOT / "evidence/distillation/local-v1/distilled-artifact.json"
            ).read_text()
        )
    verify_artifact(artifact)
    if (
        data["schema_version"] != 1
        or data["source_artifact_sha256"] != artifact["artifact_sha256"]
        or digest({k: v for k, v in data.items() if k != "data_sha256"})
        != data["data_sha256"]
    ):
        raise ValueError("Training data provenance/content drift")
    forbidden = set(held_out_hashes) | {
        digest(t["input"]) for t in discover("held-out")
    }
    template = load_task("development", "sum")
    sources = [p["run_id"] for p in artifact["provenance"]]
    seen = set()
    if not 1 <= len(data["examples"]) <= 64:
        raise ValueError("Invalid training example budget")
    for example in data["examples"]:
        inputs = example["input"]
        numbers = inputs.get("numbers")
        if (
            set(inputs) != {"numbers"}
            or not isinstance(numbers, list)
            or not 1 <= len(numbers) <= 16
            or any(type(n) is not int for n in numbers)
        ):
            raise ValueError("Invalid training input")
        identity = digest(inputs)
        if identity in forbidden | seen:
            raise ValueError("Held-out or duplicated training material")
        seen.add(identity)
        task = copy.deepcopy(template)
        task["input"] = inputs
        response = json.loads(example["response"])
        expected = str(int(sum((Fraction(n) for n in numbers), Fraction(0))))
        if (
            response != {"content": expected, "calls": []}
            or example["prompt"] != prompt_for(task)
            or example["source_runs"] != sources
        ):
            raise ValueError("Synthetic example failed independent verification")
    return data

agent_lab/optimization.py:
"""Optional adapter negotiation; absence preserves the original configuration."""


def negotiate(adapter, config, requested):
    method = getattr(adapter, "optimize", None)
    if method is None:
        return config, {
            name: {
                "status": "unavailable",
                "reason": "adapter has no optimization interface",
            }
            for name in requested
        }
    return method(config, requested)

agent_lab/oracles.py:
"""Independent full recomputation oracle for incremental ordered state."""

import bisect
import copy

from agent_lab.experiments import canonical


class IncrementalIndex:
    def __init__(self):
        self.records = {}
        self.keys = []

    def apply(self, change):
        if change["op"] == "put":
            record = copy.deepcopy(change["record"])
            record_id = record["id"]
        elif change["op"] == "delete":
            record_id = change["id"]
        else:
            raise ValueError("Unknown index operation")
        old = self.records.pop(record_id, None)
        if old is not None:
            key = (old["rank"], record_id)
            self.keys.pop(bisect.bisect_left(self.keys, key))
        if change["op"] == "put":
            self.records[record_id] = record
            bisect.insort(self.keys, (record["rank"], record_id))
        return [copy.deepcopy(self.records[record_id]) for _, record_id in self.keys]


def reference_sequence(changes):
    records = {}
    outputs = []
    for change in changes:
        if change["op"] == "put":
            records[change["record"]["id"]] = copy.deepcopy(change["record"])
        elif change["op"] == "delete":
            records.pop(change["id"], None)
        else:
            raise ValueError("Unknown reference operation")
        outputs.append(
            sorted(
                copy.deepcopy(list(records.values())),
                key=lambda value: (value["rank"], value["id"]),
            )
        )
    return outputs


def incremental_sequence(changes):
    index = IncrementalIndex()
    return [index.apply(change) for change in changes]


def differential_report(changes):
    observed = incremental_sequence(changes)
    reference = reference_sequence(changes)
    return {
        "candidate": "incremental-index-v1",
        "reference": "full-sort-v1",
        "steps": len(changes),
        "observable_equal": canonical(observed) == canonical(reference),
    }

agent_lab/permissions.py:
"""Explicit local authority, safe file traversal and owned offline process sandbox."""

import asyncio
import hashlib
import os
import secrets as secure_random
import shutil
import stat
from dataclasses import asdict, dataclass
from pathlib import Path
from urllib.parse import urlparse

from agent_lab.experiments import ROOT, digest
from agent_lab.runtime import RuntimeFailure

SCOPES = {
    "filesystem",
    "process",
    "network",
    "secrets",
    "repositories",
    "documents",
    "memory",
}
FILE_SCOPES = {"filesystem", "repositories", "documents", "memory"}
LIMIT = 1024 * 1024


class PermissionDenied(RuntimeFailure):
    """The supplied owner policy does not authorize this action."""


class SandboxUnavailable(RuntimeFailure):
    """Required native isolation is unavailable; never run unsandboxed."""


@dataclass(frozen=True)
class Grant:
    scope: str
    resource: str
    operation: str

    def __post_init__(self):
        operations = {"process": {"execute"}, "network": {"get"}, "secrets": {"handle"}}
        if (
            self.scope not in SCOPES
            or self.operation
            not in operations.get(self.scope, {"read", "write", "delete"})
            or not isinstance(self.resource, str)
            or not self.resource
        ):
            raise ValueError("Invalid explicit permission grant")
        if self.scope in FILE_SCOPES | {"process"}:
            if not Path(self.resource).is_absolute():
                raise ValueError("File/process grant needs an absolute resource")
            object.__setattr__(self, "resource", str(Path(self.resource).resolve()))


class Policy:
    def __init__(self, grants=(), emit=lambda *_: None):
        self.grants = tuple(
            sorted(set(grants), key=lambda g: (g.scope, g.resource, g.operation))
        )
        self.emit = emit
        self.identity = digest([asdict(g) for g in self.grants])

    def document(self):
        return [asdict(g) for g in self.grants]

    def require(self, scope, resource, operation):
        allowed = Grant(scope, resource, operation) in self.grants
        self.emit(
            "authority",
            {
                "action": "check",
                "scope": scope,
                "operation": operation,
                "resource_sha256": digest(resource),
                "policy_sha256": self.identity,
                "allowed": allowed,
            },
        )
        if not allowed:
            raise PermissionDenied(f"Denied {scope}/{operation}")

    def elevate(self, grant, *, reason, approval_id):
        if (
            not reason
            or len(reason) > 1280
            or not approval_id
            or len(approval_id) > 128
        ):
            raise ValueError(
                "Owner elevation needs bounded reason and approval identity"
            )
        self.emit(
            "authority",
            {
                "action": "elevation",
                "scope": grant.scope,
                "operation": grant.operation,
                "resource_sha256": digest(grant.resource),
                "reason": reason,
                "approval_id": approval_id,
            },
        )
        return Policy([*self.grants, grant], self.emit)


def _parent(root, relative):
    path = Path(relative)
    if (
        path.is_absolute()
        or not path.parts
        or any(p in ("..", ".") for p in path.parts)
    ):
        raise PermissionDenied("File path must be contained and relative")
    descriptor = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        for component in path.parts[:-1]:
            child = os.open(
                component,
                os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                dir_fd=descriptor,
            )
            os.close(descriptor)
            descriptor = child
        return descriptor, path.name
    except OSError:
        os.close(descriptor)
        raise PermissionDenied("Unsafe file traversal") from None


def _regular(descriptor):
    info = os.fstat(descriptor)
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
        raise PermissionDenied("Only ordinary unshared files are permitted")


async def _bounded(stream):
    data = bytearray()
    while chunk := await stream.read(65536):
        data.extend(chunk)
        if len(data) > LIMIT:
            raise RuntimeFailure("Sandbox output budget exceeded")
    return bytes(data).decode("utf-8", errors="replace")


class LocalTools:
    def __init__(self, policy, *, secrets=None):
        self.policy = policy
        self._secrets = dict(secrets or {})
        self._handles = {
            name: "credential:" + secure_random.token_hex(16) for name in self._secrets
        }

    def _file(self, args, operation):
        scope, root = args["scope"], str(Path(args["root"]).resolve())
        if scope not in FILE_SCOPES:
            raise PermissionDenied("Unknown file authority")
        self.policy.require(scope, root, operation)
        return _parent(root, args["path"])

    def read(self, args):
        parent, name = self._file(args, "read")
        try:
            descriptor = os.open(name, os.O_RDONLY | os.O_NOFOLLOW, dir_fd=parent)
            with os.fdopen(descriptor, "rb") as stream:
                _regular(stream.fileno())
                value = stream.read(LIMIT + 1)
                if len(value) > LIMIT:
                    raise RuntimeFailure("File read budget exceeded")
                return value.decode("utf-8")
        except OSError:
            raise PermissionDenied("Unsafe or unavailable file") from None
        finally:
            os.close(parent)

    def write(self, args):
        content = args["content"]
        if not isinstance(content, str) or len(content.encode()) > LIMIT:
            raise ValueError("Write requires bounded UTF-8 text")
        parent, name = self._file(args, "write")
        temporary = ".agent-lab-" + secure_random.token_hex(16)
        try:
            try:
                existing = os.open(name, os.O_RDONLY | os.O_NOFOLLOW, dir_fd=parent)
            except FileNotFoundError:
                existing = None
            if existing is not None:
                try:
                    _regular(existing)
                finally:
                    os.close(existing)
            descriptor = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                0o600,
                dir_fd=parent,
            )
            with os.fdopen(descriptor, "w") as stream:
                stream.write(content)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, name, src_dir_fd=parent, dst_dir_fd=parent)
            os.fsync(parent)
            return {"sha256": hashlib.sha256(content.encode()).hexdigest()}
        except OSError:
            raise PermissionDenied("Unsafe or unavailable write") from None
        finally:
            try:
                os.unlink(temporary, dir_fd=parent)
            except FileNotFoundError:
                pass
            os.close(parent)

    def delete(self, args):
        parent, name = self._file(args, "delete")
        try:
            descriptor = os.open(name, os.O_RDONLY | os.O_NOFOLLOW, dir_fd=parent)
            try:
                _regular(descriptor)
            finally:
                os.close(descriptor)
            os.unlink(name, dir_fd=parent)
            os.fsync(parent)
            return {"deleted": True}
        finally:
            os.close(parent)

    def secret_handle(self, args):
        name = args["name"]
        self.policy.require("secrets", name, "handle")
        if name not in self._handles:
            raise PermissionDenied("Credential unavailable")
        return self._handles[name]

    async def fetch(self, args):
        url = args["url"]
        parsed = urlparse(url)
        if parsed.scheme not in ("https", "http") or parsed.username or parsed.password:
            raise PermissionDenied("Unsupported network target")
        self.policy.require("network", url, "get")

        def request():
            import urllib.request

            class NoRedirect(urllib.request.HTTPRedirectHandler):
                def redirect_request(self, req, fp, code, msg, headers, newurl):
                    raise PermissionDenied("Redirect requires separate authority")

            opener = urllib.request.build_opener(
                urllib.request.ProxyHandler({}), NoRedirect()
            )
            with opener.open(url, timeout=5) as response:
                body = response.read(LIMIT + 1)
            if len(body) > LIMIT:
                raise RuntimeFailure("Network read budget exceeded")
            return body.decode("utf-8")

        return await asyncio.to_thread(request)

    async def process(self, args):
        import json

        argv = args["argv"]
        if (
            not isinstance(argv, list)
            or not 1 <= len(argv) <= 32
            or any(not isinstance(a, str) for a in argv)
            or sum(len(a) for a in argv) > 65536
        ):
            raise ValueError("Process needs bounded argv")
        executable = str(Path(argv[0]).resolve())
        self.policy.require("process", executable, "execute")
        timeout = args.get("timeout", 5)
        if (
            isinstance(timeout, bool)
            or not isinstance(timeout, (int, float))
            or not 0 < timeout <= 60
        ):
            raise ValueError("Process timeout must be 0..60 seconds")
        pin = json.loads((ROOT / "configurations/sandbox-v1.json").read_text())
        binary = shutil.which("bwrap")
        if (
            binary is None
            or hashlib.sha256(Path(binary).read_bytes()).hexdigest()
            != pin["bubblewrap_sha256"]
        ):
            raise SandboxUnavailable("Pinned bubblewrap binary unavailable")
        command = [
            binary,
            "--unshare-all",
            "--die-with-parent",
            "--new-session",
            "--cap-drop",
            "ALL",
            "--ro-bind",
            "/usr",
            "/usr",
        ]
        for path in ("/lib", "/lib64"):
            if Path(path).exists():
                command += ["--ro-bind", path, path]
        command += [
            "--proc",
            "/proc",
            "--dev",
            "/dev",
            "--tmpfs",
            "/tmp",
            "--clearenv",
            "--setenv",
            "PATH",
            "/usr/bin",
            "--setenv",
            "LC_ALL",
            "C.UTF-8",
            "--setenv",
            "TZ",
            "UTC",
            "--chdir",
            "/tmp",
        ]
        roots = sorted(
            {
                g.resource
                for g in self.policy.grants
                if g.scope in FILE_SCOPES and g.operation == "read"
            }
        )
        for index, root in enumerate(roots):
            command += ["--ro-bind", root, f"/scopes/{index}"]
        # Subprocesses always have offline read-only persistent mounts. Writes use
        # the separately scoped native file tool, never inherited process authority.
        command += ["--", executable, *argv[1:]]
        launch = asyncio.create_task(
            asyncio.create_subprocess_exec(
                *command,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                start_new_session=True,
            )
        )
        process = None
        try:
            process = await asyncio.shield(launch)
            async with asyncio.timeout(timeout):
                async with asyncio.TaskGroup() as group:
                    stdout = group.create_task(_bounded(process.stdout))
                    stderr = group.create_task(_bounded(process.stderr))
                    group.create_task(process.wait())
            result = {
                "returncode": process.returncode,
                "stdout": stdout.result(),
                "stderr": stderr.result(),
            }
            if process.returncode and ("bwrap:" in result["stderr"]):
                raise SandboxUnavailable("Required namespace isolation unavailable")
            return result
        finally:
            if process is None:
                process = await launch
            if process.returncode is None:
                process.kill()
            await process.wait()

    def registry(self):
        return {
            "read_file": self.read,
            "write_file": self.write,
            "delete_file": self.delete,
            "credential_handle": self.secret_handle,
            "http_get": self.fetch,
            "run_process": self.process,
        }

    @property
    def idempotent_tools(self):
        return {"read_file", "credential_handle"}

agent_lab/release.py:
"""Fixed-hardware release reporting; missing evidence never becomes a pass."""

import argparse
import hashlib
import json
import math
from dataclasses import asdict
from pathlib import Path

from jsonschema import Draft202012Validator

from agent_lab.experiments import MEASUREMENTS, ROOT, canonical, digest, validate_result
from agent_lab.runtime import AgentConfig
from agent_lab.trace import load_trace


def validate_profile(profile):
    schema = json.loads((ROOT / "schemas/release-profile-v1.json").read_text())
    Draft202012Validator(schema).validate(profile)
    canonical(profile)
    workloads = profile["workloads"]
    configuration = profile["configuration"]
    if asdict(AgentConfig(**configuration)) != configuration:
        raise ValueError("Release configuration must declare every runtime field")
    variable = {
        "seed",
        "context_size",
        "max_output_tokens",
        "max_steps",
        "max_tool_calls",
        "options",
    }
    for workload in workloads:
        candidate = workload["configuration"]
        if (
            asdict(AgentConfig(**candidate)) != candidate
            or any(
                candidate[key] != value
                for key, value in configuration.items()
                if key not in variable
            )
            or any(
                candidate["options"].get(key) != value
                for key, value in configuration["options"].items()
            )
        ):
            raise ValueError(
                "One release candidate cannot mix model or backend identities"
            )
    ids = [w["task"]["id"] for w in workloads]
    thresholds = profile["thresholds"]
    if len(ids) != len(set(ids)) or len({t["id"] for t in thresholds}) != len(
        thresholds
    ):
        raise ValueError("Release identities must be unique")
    for threshold in thresholds:
        if threshold["source"] == "runs":
            if not set(threshold["workloads"]).issubset(ids):
                raise ValueError("Unknown release workload")
            if threshold["aggregation"] == "success_rate":
                if threshold["field"] != "correctness.status":
                    raise ValueError("Success rate requires independent correctness")
            elif threshold["field"] not in (
                {"measurements." + name for name in MEASUREMENTS}
                | {"configuration.context_size"}
            ):
                raise ValueError("Unknown release measurement")
        elif threshold["aggregation"] != "value":
            raise ValueError("Proof thresholds use explicit values")
    return profile


def family(configuration):
    return {k: v for k, v in configuration.items() if k != "seed"}


def status_for(value, threshold):
    if value is None:
        return "unavailable"
    comparison = (
        value >= threshold["limit"]
        if threshold["operator"] == ">="
        else value <= threshold["limit"]
    )
    return "pass" if comparison else "fail"


def combined(statuses):
    if "fail" in statuses:
        return "fail"
    if not statuses or "unavailable" in statuses:
        return "unavailable"
    return "pass"


def release_report(profile, runs, proofs, software):
    validate_profile(profile)
    if (
        proofs.get("profile_sha256") != digest(profile)
        or proofs.get("hardware") != profile["hardware"]
        or proofs.get("software") != software
        or proofs.get("configuration") != profile["configuration"]
    ):
        raise ValueError("Scaffold proof authority drift")
    expected = {w["task"]["id"]: w for w in profile["workloads"]}
    groups = {identifier: [] for identifier in expected}
    repeats, identifiers = set(), set()
    for sample in runs:
        validate_result(sample)
        identifier = sample["task"]["id"]
        workload = expected.get(identifier)
        if workload is None:
            raise ValueError("Undeclared release workload")
        if (
            sample["task"] != workload["task"]
            or {k: v for k, v in sample["protocol"].items() if k != "repeat"}
            != workload["protocol"]
            or family(sample["configuration"]) != family(workload["configuration"])
            or sample["hardware"] != profile["hardware"]
            or sample["software"] != software
            or sample["correctness"]["evaluator"] != workload["protocol"]["id"]
        ):
            raise ValueError("Release workload, configuration or environment drift")
        repeat = (identifier, sample["protocol"]["repeat"])
        if repeat in repeats or sample["run_id"] in identifiers:
            raise ValueError("Duplicate release sample")
        repeats.add(repeat)
        identifiers.add(sample["run_id"])
        groups[identifier].append(sample)
    entries = []
    for threshold in profile["thresholds"]:
        details = []
        if threshold["source"] == "proofs":
            proof = proofs["values"].get(threshold["field"], {})
            value = proof.get("value")
            if value is not None and (
                type(value) not in (int, float) or not math.isfinite(value)
            ):
                raise ValueError("Proof value must be finite numeric or unavailable")
            details.append(
                {
                    "value": value,
                    "status": status_for(value, threshold),
                    "scope": proof.get("scope", "No matching proof"),
                    "evidence": proof.get("evidence", []),
                }
            )
        else:
            for identifier in threshold["workloads"]:
                samples = groups[identifier]
                aggregation = threshold["aggregation"]
                values = []
                if aggregation == "success_rate":
                    values = [
                        float(
                            s["correctness"]["status"] == "pass"
                            and s["work"]["tool_calls"] is not None
                            and s["work"]["tool_calls"]
                            >= threshold.get("minimum_tool_calls", 0)
                        )
                        for s in samples
                    ]
                else:
                    section, name = threshold["field"].split(".", 1)
                    values = [s[section].get(name) for s in samples]
                value = None
                if len(samples) >= profile["minimum_repeats"] and all(
                    v is not None for v in values
                ):
                    if aggregation == "success_rate":
                        value = sum(values) / len(values)
                    elif aggregation == "p95":
                        value = sorted(values)[math.ceil(0.95 * len(values)) - 1]
                    elif aggregation == "max":
                        value = max(values)
                    elif aggregation == "min":
                        value = min(values)
                details.append(
                    {
                        "workload": identifier,
                        "samples": len(samples),
                        "available_samples": sum(v is not None for v in values),
                        "value": value,
                        "status": status_for(value, threshold),
                    }
                )
        entries.append(
            {
                **threshold,
                "status": combined([d["status"] for d in details]),
                "details": details,
            }
        )
    required = [entry["status"] for entry in entries if entry["required"]]
    status = combined(required)
    return {
        "schema_version": 1,
        "tier": profile["id"],
        "profile_sha256": digest(profile),
        "configuration": profile["configuration"],
        "hardware": profile["hardware"],
        "software": software,
        "samples": len(runs),
        "status": status,
        "ready": status == "pass",
        "thresholds": entries,
        "scope": profile["scope"],
    }


def load_bundle(profile, root):
    root = Path(root).resolve()
    manifest = json.loads((root / "manifest.json").read_text())
    if manifest["schema_version"] != 1 or manifest["profile_sha256"] != digest(profile):
        raise ValueError("Release bundle/profile drift")
    required = {
        "results.jsonl",
        "cold-results.jsonl",
        "proofs.json",
        "profile.json",
        "measured-source.json",
    }
    if not required.issubset(manifest["files"]):
        raise ValueError("Release manifest is incomplete")
    for name, expected in manifest["files"].items():
        path = (root / name).resolve()
        if not path.is_relative_to(root) or not path.is_file():
            raise ValueError("Contained release artifact required")
        if hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError("Release artifact drift: " + name)
    if (
        json.loads((root / "profile.json").read_text()) != profile
        or digest(json.loads((root / "measured-source.json").read_text()))
        != manifest["software"]["source_hash"]
    ):
        raise ValueError("Measured source/profile drift")
    runs = [
        json.loads(line) for line in (root / "results.jsonl").read_text().splitlines()
    ]
    cold = [
        json.loads(line)
        for line in (root / "cold-results.jsonl").read_text().splitlines()
    ]
    if len(cold) != len(profile["workloads"]) or any(
        s["protocol"]["repeat"] != profile["minimum_repeats"]
        or s["configuration"]["seed"] != 99
        for s in cold
    ):
        raise ValueError("Cold-load cohort is incomplete or misclassified")
    if any(s["protocol"]["repeat"] >= profile["minimum_repeats"] for s in runs):
        raise ValueError("Cold/extra samples cannot enter the fixed warm cohort")
    for sample in [*runs, *cold]:
        for name in ("result.json", "trace.json"):
            if f"runs/{sample['run_id']}/{name}" not in manifest["files"]:
                raise ValueError("Unbound release result/trace")
        run_root = root / "runs" / sample["run_id"]
        trace = load_trace(run_root / "trace.json", artifact_root=run_root)
        if (
            json.loads((run_root / "result.json").read_text()) != sample
            or trace["run_id"] != sample["run_id"]
            or trace["task_id"] != sample["task"]["id"]
            or trace["configuration_id"] != digest(sample["configuration"])
            or trace["artifacts"] != sample["artifacts"]
        ):
            raise ValueError("Release result/trace drift")
        evaluations = [e for e in trace["events"] if e["kind"] == "evaluator"]
        measurements = [e for e in trace["events"] if e["kind"] == "measurements"]
        if (
            not evaluations
            or evaluations[-1]["metadata"] != sample["correctness"]
            or not measurements
            or measurements[-1]["metadata"]
            != {
                "values": sample["measurements"],
                "sources": sample["measurement_sources"],
            }
        ):
            raise ValueError("Release authority/measurement trace drift")
        if sample["task"]["id"] != "repository-unknown-usage" and sample["correctness"][
            "status"
        ] in ("pass", "fail"):
            from agent_lab.benchmarks import load_task
            from agent_lab.evaluators import independent_evaluate

            task = load_task(sample["protocol"]["split"], sample["task"]["id"])
            output = json.loads((run_root / "output.json").read_text())["content"]
            if (
                digest(task) != sample["task"]["fixture_hash"]
                or independent_evaluate(task, output) != sample["correctness"]
            ):
                raise ValueError("Independent release evaluation drift")
        elif sample["task"]["id"] == "repository-unknown-usage":
            verification = json.loads((run_root / "verification.json").read_text())
            if {
                k: verification["after"][k] for k in ("status", "score", "evaluator")
            } != (sample["correctness"]):
                raise ValueError("Protected repository evaluation drift")
    proofs = json.loads((root / "proofs.json").read_text())
    release_report(profile, cold, proofs, manifest["software"])
    return release_report(profile, runs, proofs, manifest["software"])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--profile", type=Path, required=True)
    parser.add_argument("--bundle", type=Path, required=True)
    args = parser.parse_args()
    profile = json.loads(args.profile.read_text())
    report = load_bundle(profile, args.bundle)
    print(canonical(report))
    return {"pass": 0, "unavailable": 1, "fail": 2}[report["status"]]


if __name__ == "__main__":
    raise SystemExit(main())

agent_lab/repository_checker.py:
"""Trusted observation worker; candidate input is structurally bounded by parent."""

import asyncio
import importlib.util
import json
import sys
from dataclasses import asdict
from pathlib import Path


def snapshot(state):
    value = asdict(state)
    return {
        k: value[k]
        for k in (
            "input_tokens",
            "output_tokens",
            "model_calls",
            "tool_calls",
            "status",
            "output",
        )
    }


async def observations(path):
    spec = importlib.util.spec_from_file_location("historical_runtime", path)
    runtime = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = runtime
    spec.loader.exec_module(runtime)
    results = {}

    def failed(*_):
        raise runtime.RuntimeFailure("unknown completion")

    state = runtime.AgentState("first unknown")
    try:
        await runtime.run(
            runtime.FunctionAdapter(failed), {}, runtime.AgentConfig(), state
        )
    except runtime.RuntimeFailure:
        pass
    results["first_unknown"] = snapshot(state)

    async def waiting(*_):
        await asyncio.sleep(30)

    class Waiting:
        complete = staticmethod(waiting)

    state = runtime.AgentState("cancel unknown")
    job = asyncio.create_task(runtime.run(Waiting(), {}, runtime.AgentConfig(), state))
    await asyncio.sleep(0)
    job.cancel()
    try:
        await job
    except asyncio.CancelledError:
        pass
    results["cancel_unknown"] = snapshot(state)
    state = runtime.AgentState("known response")
    await runtime.run(
        runtime.SequenceAdapter(
            [runtime.Reply("done", input_tokens=2, output_tokens=3)]
        ),
        {},
        runtime.AgentConfig(),
        state,
    )
    results["known_response"] = snapshot(state)
    state = runtime.AgentState("known tool failure")
    try:
        await runtime.run(
            runtime.SequenceAdapter(
                [
                    runtime.Reply(
                        calls=(runtime.ToolCall("fail", {}),),
                        input_tokens=2,
                        output_tokens=3,
                    )
                ]
            ),
            {"fail": failed},
            runtime.AgentConfig(),
            state,
        )
    except runtime.RuntimeFailure:
        pass
    results["known_tool_failure"] = snapshot(state)
    state = runtime.AgentState("later unknown")

    def later(messages, _):
        if messages[-1]["role"] == "tool":
            return failed()
        return runtime.Reply(
            calls=(runtime.ToolCall("echo", {}),), input_tokens=2, output_tokens=3
        )

    try:
        await runtime.run(
            runtime.FunctionAdapter(later),
            {"echo": lambda _: 1},
            runtime.AgentConfig(),
            state,
        )
    except runtime.RuntimeFailure:
        pass
    results["later_unknown"] = snapshot(state)
    return results


if __name__ == "__main__":
    print(json.dumps(asyncio.run(observations(Path(sys.argv[1]))), sort_keys=True))

agent_lab/repository_workload.py:
"""Historical repository fixtures with live policy and protected executable grading."""

import ast
import hashlib
import json
import shutil
import subprocess
from pathlib import Path

from agent_lab.experiments import ROOT
from agent_lab.permissions import Grant, LocalTools, Policy
from agent_lab.runtime import RuntimeFailure

FIXTURE = ROOT / "benchmarks/repositories/unknown-usage-v1"
NEEDLE = "                    await asyncio.sleep(config.retry_delay * 2**attempt)\n"
ADDITION = (
    "                except Exception, asyncio.CancelledError:\n"
    "                    state.input_tokens = state.output_tokens = None\n"
    "                    raise\n"
)


class RepositorySetupUnavailable(RuntimeFailure):
    """Live policy cannot be resolved; never invent substitute conventions."""


def fixture_manifest():
    manifest = json.loads((FIXTURE / "manifest.json").read_text())
    for name, expected in manifest["files"].items():
        if hashlib.sha256((FIXTURE / name).read_bytes()).hexdigest() != expected:
            raise ValueError("Historical fixture drift")
    return manifest


def reference_patch(source):
    if source.count(NEEDLE) != 1:
        raise ValueError("Historical request seam changed")
    return source.replace(NEEDLE, NEEDLE + ADDITION)


def _request_try(tree):
    for node in ast.walk(tree):
        if (
            isinstance(node, ast.Try)
            and any(isinstance(statement, ast.AsyncWith) for statement in node.body)
            and any(
                isinstance(child, ast.Await)
                and isinstance(child.value, ast.Call)
                and isinstance(child.value.func, ast.Attribute)
                and child.value.func.attr == "complete"
                for child in ast.walk(ast.Module(body=node.body, type_ignores=[]))
            )
        ):
            return node
    raise ValueError("Adapter request boundary absent")


def safe_patch(original, candidate):
    """Allow only side-effect-free null accounting plus re-raise at one seam."""
    try:
        before, after = ast.parse(original), ast.parse(candidate)
        initial, changed = _request_try(before), _request_try(after)
        if len(changed.handlers) != len(initial.handlers) + 1:
            return False
        handler = changed.handlers.pop()
        expected_type = (
            ast.parse("try:\n pass\nexcept Exception, asyncio.CancelledError:\n pass\n")
            .body[0]
            .handlers[0]
            .type
        )
        if (
            ast.dump(handler.type) != ast.dump(expected_type)
            or handler.name is not None
            or not handler.body
        ):
            return False
        fields = []
        for statement in handler.body[:-1]:
            if (
                not isinstance(statement, ast.Assign)
                or not isinstance(statement.value, ast.Constant)
                or statement.value.value is not None
            ):
                return False
            for target in statement.targets:
                if (
                    not isinstance(target, ast.Attribute)
                    or not isinstance(target.value, ast.Name)
                    or target.value.id != "state"
                ):
                    return False
                fields.append(target.attr)
        if sorted(fields) != ["input_tokens", "output_tokens"]:
            return False
        last = handler.body[-1]
        if (
            not isinstance(last, ast.Raise)
            or last.exc is not None
            or last.cause is not None
        ):
            return False
        return ast.dump(before) == ast.dump(after)
    except SyntaxError, ValueError:
        return False


def resolve_conventions(workspace):
    cli = Path("/home/moenarch/moritzbrantner/coding-tooling/src/cli.ts")
    registry = Path("/home/moenarch/.config/moenarch/environment.toml")
    bun = shutil.which("bun")
    if not bun or not cli.is_file() or not registry.is_file():
        raise RepositorySetupUnavailable(
            "Live shared convention tooling/registry unavailable"
        )
    response = subprocess.run(
        [
            bun,
            str(cli),
            "conventions",
            "resolve",
            "--root",
            str(workspace),
            "--registry",
            str(registry),
            "--json",
        ],
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    document = json.loads(response.stdout)
    if response.returncode or document["status"] != "passed":
        raise RepositorySetupUnavailable("Shared convention resolution failed")
    stack = document["data"]
    files = []
    for entry in stack["files"]:
        content = Path(entry["absolutePath"]).read_text()
        files.append(
            {
                "path": entry["path"],
                "sha256": hashlib.sha256(content.encode()).hexdigest(),
            }
        )
    local = {
        name: (Path(workspace) / name).read_text()
        for name in ("AGENTS.md", "CLAUDE.md")
        if (Path(workspace) / name).exists()
    }
    return {
        "sourceRevision": stack["sourceRevision"],
        "technologies": stack["technologies"],
        "files": files,
        "local_instructions": local,
    }


def _expected():
    def value(inputs, outputs, calls, tools, status, output=""):
        return {
            "input_tokens": inputs,
            "output_tokens": outputs,
            "model_calls": calls,
            "tool_calls": tools,
            "status": status,
            "output": output,
        }

    return {
        "first_unknown": value(None, None, 1, 0, "failed"),
        "cancel_unknown": value(None, None, 1, 0, "cancelled"),
        "known_response": value(2, 3, 1, 0, "completed", "done"),
        "known_tool_failure": value(2, 3, 1, 0, "failed"),
        "later_unknown": value(None, None, 2, 1, "failed"),
    }


async def check_patch(workspace, *, allow_baseline=False):
    workspace = Path(workspace).resolve()
    original = (FIXTURE / "runtime.py").read_text()
    manifest = fixture_manifest()
    for name, expected in manifest["files"].items():
        if (
            name != "runtime.py"
            and hashlib.sha256((workspace / name).read_bytes()).hexdigest() != expected
        ):
            return {
                "status": "fail",
                "score": 0,
                "evaluator": manifest["checker"],
                "reason": "repository authority changed",
            }
    candidate = (workspace / "runtime.py").read_text()
    if not (allow_baseline and candidate == original) and not safe_patch(
        original, candidate
    ):
        return {
            "status": "fail",
            "score": 0,
            "evaluator": manifest["checker"],
            "reason": "patch outside reviewed historical seam",
        }
    policy = Policy(
        [
            Grant("process", "/usr/bin/python3.14", "execute"),
            Grant("repositories", str(workspace), "read"),
        ]
    )
    source = (ROOT / "agent_lab/repository_checker.py").read_text()
    # Trusted worker observes behavior; expected values remain in the parent.
    result = await LocalTools(policy).process(
        {
            "argv": [
                "/usr/bin/python3.14",
                "-I",
                "-S",
                "-c",
                source,
                "/scopes/0/runtime.py",
            ],
            "timeout": 10,
        }
    )
    if result["returncode"]:
        return {
            "status": "error",
            "score": None,
            "evaluator": manifest["checker"],
            "reason": "isolated observation failed",
        }
    observed = json.loads(result["stdout"])
    expected = _expected()
    passed = observed == expected
    return {
        "status": "pass" if passed else "fail",
        "score": int(passed),
        "evaluator": manifest["checker"],
        "observations": observed,
        "failed_criteria": [
            name for name in expected if observed.get(name) != expected[name]
        ],
    }


class RepositoryTools:
    def __init__(self, workspace, emit):
        self.workspace = Path(workspace).resolve()
        self.policy = Policy(
            [
                Grant("repositories", str(self.workspace), operation)
                for operation in ("read", "write")
            ],
            emit,
        )
        self.native = LocalTools(self.policy)

    def read(self, args):
        name = args["path"]
        if name not in ("runtime.py", "AGENTS.md", "pyproject.toml"):
            raise ValueError("Repository fixture read outside declared files")
        return self.native.read(
            {"scope": "repositories", "root": str(self.workspace), "path": name}
        )

    def replace(self, args):
        old, new = args["old"], args["new"]
        if (
            not isinstance(old, str)
            or not isinstance(new, str)
            or not old
            or max(len(old), len(new)) > 8192
        ):
            raise ValueError("Edit must be a bounded exact replacement")
        text = self.read({"path": "runtime.py"})
        if text.count(old) != 1:
            raise ValueError("Replacement must match exactly once")
        return self.native.write(
            {
                "scope": "repositories",
                "root": str(self.workspace),
                "path": "runtime.py",
                "content": text.replace(old, new),
            }
        )

    async def check(self, args):
        result = await check_patch(self.workspace)
        return {k: v for k, v in result.items() if k != "observations"}

    def registry(self):
        return {
            "read_source": self.read,
            "replace_text": self.replace,
            "check_patch": self.check,
        }

agent_lab/routing.py:
"""Bounded cheap-first/role routing with observable decisions and complete work."""

import re
from dataclasses import asdict, dataclass, replace

from agent_lab.experiments import digest
from agent_lab.runtime import AgentConfig, Reply, ResponseFailure, RuntimeFailure


@dataclass(frozen=True)
class Requirements:
    tools: tuple[str, ...] = ()
    minimum_tool_results: int = 0
    output_kind: str = "text"

    def completed(self, messages):
        return sum(message["role"] == "tool" for message in messages)

    def reject(self, reply, messages):
        if any(call.name not in self.tools for call in reply.calls):
            return "unknown-tool"
        if not reply.calls:
            if not reply.content.strip():
                return "empty-reply"
            if self.completed(messages) < self.minimum_tool_results:
                return "incomplete-required-tools"
            if self.output_kind == "integer" and not re.fullmatch(
                r"-?[0-9]+", reply.content
            ):
                return "invalid-answer-shape"
        return None


def combine(replies, final=None):
    final = final or replies[-1]
    totals = {}
    for name in ("input_tokens", "output_tokens"):
        values = [getattr(reply, name) for reply in replies]
        totals[name] = sum(values) if all(v is not None for v in values) else None
    keys = (
        set.intersection(*(set(reply.measurements) for reply in replies))
        if replies
        else set()
    )
    measurements = {
        key: sum(reply.measurements[key] for reply in replies) for key in keys
    }
    return Reply(
        final.content,
        final.calls,
        totals["input_tokens"],
        totals["output_tokens"],
        measurements,
        sum(reply.model_calls for reply in replies),
    )


class RoutingAdapter:
    def __init__(
        self,
        cheap,
        cheap_config,
        strong,
        strong_config,
        requirements=None,
        *,
        max_escalations=1,
        max_calls=16,
        mode="cheap-first",
    ):
        if (
            max_escalations < 0
            or max_calls < 1
            or mode not in ("cheap-first", "role-specialized")
        ):
            raise ValueError("Invalid routing policy")
        requirements = requirements or Requirements()
        self.adapters = {"cheap": cheap, "strong": strong}
        self.configs = {"cheap": cheap_config, "strong": strong_config}
        self.requirements = requirements
        self.max_escalations, self.max_calls, self.mode = (
            max_escalations,
            max_calls,
            mode,
        )
        self.escalations = self.calls = 0
        self.forced_strong = False
        self.emit = lambda kind, payload: None
        self.policy = {
            "models": {k: asdict(v) for k, v in self.configs.items()},
            "requirements": asdict(requirements),
            "mode": mode,
            "max_escalations": max_escalations,
            "max_calls": max_calls,
        }
        self.identity = digest(self.policy)

    @property
    def invocation_count(self):
        return self.calls

    def observe(self, emit):
        self.emit = emit

    def configuration(self, **overrides):
        return AgentConfig(
            model="routing-v1",
            model_digest=self.identity,
            backend="routing",
            quantization="mixed",
            options=self.policy,
            **overrides,
        )

    async def _attempt(self, tier, messages, outer):
        if self.calls >= self.max_calls:
            raise ResponseFailure(
                "Routing call budget exhausted",
                input_tokens=0,
                output_tokens=0,
                model_calls=0,
            )
        self.calls += 1
        config = replace(
            self.configs[tier],
            seed=outer.seed,
            request_timeout=min(
                outer.request_timeout, self.configs[tier].request_timeout
            ),
        )
        child = f"routing:{self.calls}"
        self.emit(
            "child",
            {
                "child_id": child,
                "stage": tier,
                "model_digest": config.model_digest,
                "kind": "model_request",
                "messages": messages,
                "configuration": asdict(config),
            },
        )
        try:
            reply = await self.adapters[tier].complete(messages, config)
        except ResponseFailure as error:
            self.emit(
                "child",
                {
                    "child_id": child,
                    "stage": tier,
                    "kind": "model_response",
                    "failure": True,
                    "usage": asdict(error.usage),
                },
            )
            raise
        except RuntimeFailure as error:
            raise ResponseFailure("Backend completion unknown") from error
        self.emit(
            "child",
            {
                "child_id": child,
                "stage": tier,
                "kind": "model_response",
                "reply": asdict(reply),
            },
        )
        return reply

    async def complete(self, messages, config):
        if config.model_digest != self.identity or config.backend != "routing":
            raise ResponseFailure(
                "Routing identity mismatch",
                input_tokens=0,
                output_tokens=0,
                model_calls=0,
            )
        completed = self.requirements.completed(messages)
        tier = (
            "strong"
            if (
                self.forced_strong
                or (
                    self.mode == "role-specialized"
                    and completed < self.requirements.minimum_tool_results
                )
            )
            else "cheap"
        )
        self.emit(
            "routing",
            {
                "stage": tier,
                "reason": "policy-selection",
                "completed_tools": completed,
                "model_digest": self.configs[tier].model_digest,
                "budget_remaining": self.max_calls - self.calls,
            },
        )
        replies = []
        try:
            reply = await self._attempt(tier, messages, config)
            replies.append(reply)
            reason = self.requirements.reject(reply, messages)
        except ResponseFailure as error:
            replies.append(error.usage)
            reason = "malformed-or-failed-response"
        if reason is None:
            return combine(replies)
        if tier == "strong" or self.escalations >= self.max_escalations:
            usage = combine(replies)
            raise ResponseFailure(
                "Routing validation/escalation budget failed",
                input_tokens=usage.input_tokens,
                output_tokens=usage.output_tokens,
                measurements=usage.measurements,
                model_calls=usage.model_calls,
            )
        self.escalations += 1
        self.forced_strong = True
        self.emit(
            "routing",
            {
                "stage": "strong",
                "reason": reason,
                "completed_tools": completed,
                "model_digest": self.configs["strong"].model_digest,
                "budget_remaining": self.max_calls - self.calls,
            },
        )
        try:
            strong = await self._attempt("strong", messages, config)
            replies.append(strong)
            reason = self.requirements.reject(strong, messages)
        except ResponseFailure as error:
            replies.append(error.usage)
            reason = "failed-strong-response"
        usage = combine(replies)
        if reason:
            raise ResponseFailure(
                "Strong response rejected",
                input_tokens=usage.input_tokens,
                output_tokens=usage.output_tokens,
                measurements=usage.measurements,
                model_calls=usage.model_calls,
            )
        return usage

agent_lab/routing_experiment.py:
"""Compare single-model, cheap-first and role-specialized local agents."""

import argparse
import asyncio
import json
from dataclasses import replace
from pathlib import Path

from agent_lab.backends import OllamaAdapter
from agent_lab.baselines import inventory, unload_experiment_models, validate_manifest
from agent_lab.benchmarks import benchmark, load_task
from agent_lab.experiments import ROOT, canonical, compare, digest, summarize
from agent_lab.routing import Requirements, RoutingAdapter
from agent_lab.runtime import AgentConfig
from agent_lab.telemetry import hardware_profile, software_identity
from agent_lab.trace import atomic_json


async def experiment(output):
    if output.exists():
        raise ValueError("Choose a new evidence directory")
    manifest = json.loads((ROOT / "configurations/local-baselines-v1.json").read_text())
    cheap = AgentConfig(**manifest["profiles"]["small-q4-cpu"])
    strong = AgentConfig(**manifest["profiles"]["medium-q4-gpu"])
    for config in (cheap, strong):
        from dataclasses import asdict

        validate_manifest(asdict(config), *inventory())
    hardware, software = hardware_profile(), software_identity()
    if hardware != manifest["hardware"]:
        raise ValueError("Hardware drift")
    allowed = {p["model"] for p in manifest["profiles"].values()}
    task = load_task("development", "batch-sum")
    output.mkdir(parents=True)
    groups = {}
    cold = []
    for label in ("single-cheap", "single-strong", "cheap-first", "role-specialized"):
        await asyncio.to_thread(unload_experiment_models, allowed)
        groups[label] = []
        for repeat in range(6):
            if label.startswith("single"):
                config = replace(
                    cheap if label == "single-cheap" else strong, seed=repeat
                )
                adapter = OllamaAdapter()
            else:
                adapter = RoutingAdapter(
                    OllamaAdapter(),
                    cheap,
                    OllamaAdapter(),
                    strong,
                    Requirements(("sum",), 3, "integer"),
                    mode=label,
                )
                config = adapter.configuration(seed=repeat)
            result = await benchmark(
                task,
                adapter,
                config,
                repeat=repeat,
                hardware=hardware,
                software=software,
                output_root=output / "runs",
            )
            if repeat == 5:
                groups[label].append(result)
            elif repeat == 0:
                cold.append(result)
            else:
                groups[label].append(result)
            print(
                canonical(
                    {
                        "configuration": label,
                        "repeat": repeat,
                        "status": result["correctness"]["status"],
                    }
                ),
                flush=True,
            )
    # Repeats 1..5 are steady state after separately retained repeat 0.
    report = {
        label: {
            "passed": sum(r["correctness"]["status"] == "pass" for r in results),
            "summary": summarize(results),
        }
        for label, results in groups.items()
    }
    report["comparisons"] = {
        label: [
            compare(a, b)
            for a, b in zip(groups["single-strong"], groups[label], strict=True)
        ]
        for label in ("cheap-first", "role-specialized")
    }
    results = [r for group in groups.values() for r in group]
    (output / "results.jsonl").write_text("".join(canonical(r) + "\n" for r in results))
    atomic_json(output / "cold-results.json", cold)
    atomic_json(output / "report.json", report)
    atomic_json(
        output / "manifest.json",
        {
            "schema_version": 1,
            "results_sha256": digest(results),
            "cold_sha256": digest(cold),
        },
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    asyncio.run(experiment(parser.parse_args().output))


if __name__ == "__main__":
    main()

agent_lab/runtime.py:
"""Bounded orchestration with explicit state and backend-independent messages."""

import asyncio
import copy
import inspect
from dataclasses import asdict, dataclass, field
from typing import Protocol

from agent_lab.context import project_context


class RuntimeFailure(Exception):
    """A permanent runtime or tool failure."""


class TransientModelError(RuntimeFailure):
    """An adapter declares that a request failed safely before completion."""


@dataclass(frozen=True)
class AgentConfig:
    model: str = "fixture"
    model_digest: str = "fixture-v1"
    backend: str = "fixture"
    backend_version: str = "1"
    quantization: str = "none"
    seed: int = 0
    temperature: float = 0
    context_size: int = 4096
    max_output_tokens: int = 256
    max_steps: int = 8
    max_retries: int = 2
    max_tool_calls: int = 16
    request_timeout: float = 60
    retry_delay: float = 0.1
    context_policy: str = "full"
    feedback: str = ""
    options: dict = field(default_factory=dict)

    def __post_init__(self):
        if self.context_policy not in ("full", "retained", "relevance"):
            raise ValueError("Unknown context policy")
        if min(self.max_steps, self.max_output_tokens, self.context_size) < 1:
            raise ValueError("Step, token and context budgets must be positive")
        if min(self.max_retries, self.max_tool_calls, self.retry_delay) < 0:
            raise ValueError("Retry/tool budgets and delay cannot be negative")
        if self.request_timeout <= 0:
            raise ValueError("Request timeout must be positive")


@dataclass(frozen=True)
class ToolCall:
    name: str
    arguments: dict


@dataclass(frozen=True)
class Reply:
    content: str = ""
    calls: tuple[ToolCall, ...] = ()
    input_tokens: int | None = None
    output_tokens: int | None = None
    measurements: dict = field(default_factory=dict)
    model_calls: int = 1

    @classmethod
    def parse(cls, value):
        if not isinstance(value, dict) or not isinstance(value.get("content", ""), str):
            raise RuntimeFailure("Invalid model reply")
        calls = value.get("calls", [])
        if not isinstance(calls, list):
            raise RuntimeFailure("Invalid tool calls")
        parsed = []
        for call in calls:
            if (
                not isinstance(call, dict)
                or not isinstance(call.get("name"), str)
                or not isinstance(call.get("arguments"), dict)
            ):
                raise RuntimeFailure("Invalid tool call")
            parsed.append(ToolCall(call["name"], call["arguments"]))
        for key in ("input_tokens", "output_tokens"):
            count = value.get(key)
            if count is not None and (type(count) is not int or count < 0):
                raise RuntimeFailure("Invalid token count")
        if (
            type(value.get("model_calls", 1)) is not int
            or value.get("model_calls", 1) < 0
        ):
            raise RuntimeFailure("Invalid invocation count")
        return cls(
            value.get("content", ""),
            tuple(parsed),
            value.get("input_tokens"),
            value.get("output_tokens"),
            value.get("measurements", {}),
            value.get("model_calls", 1),
        )


class ResponseFailure(RuntimeFailure):
    """A completed but unusable response, retaining its consumed resources."""

    def __init__(
        self,
        message,
        *,
        input_tokens=None,
        output_tokens=None,
        measurements=None,
        model_calls=1,
    ):
        super().__init__(message)
        self.usage = Reply(
            input_tokens=input_tokens,
            output_tokens=output_tokens,
            measurements=measurements or {},
            model_calls=model_calls,
        )


class ModelAdapter(Protocol):
    async def complete(self, messages: list[dict], config: AgentConfig) -> Reply: ...


class SequenceAdapter:
    """Recorded deterministic responses, owned by one run."""

    def __init__(self, replies):
        self.replies = iter(replies)

    async def complete(self, messages, config):
        try:
            return next(self.replies)
        except StopIteration as error:
            raise RuntimeFailure("Fixture responses exhausted") from error


class FunctionAdapter:
    """A deterministic fixture driven by observable messages."""

    def __init__(self, respond):
        self.respond = respond

    async def complete(self, messages, config):
        return self.respond(messages, config)


@dataclass
class AgentState:
    task: str
    messages: list[dict] = field(default_factory=list)
    status: str = "pending"
    output: str = ""
    steps: int = 0
    model_calls: int = 0
    retries: int = 0
    tool_calls: int = 0
    input_tokens: int | None = 0
    output_tokens: int | None = 0
    pending_calls: list[dict] = field(default_factory=list)
    working_memory: list[dict] = field(default_factory=list)
    active_call: dict | None = None
    request_in_flight: bool = False
    request_attempts: int = 0


def _ignore_event(kind, payload):
    """Default hook intentionally retains no content."""


async def run(adapter, tools, config, state, emit=_ignore_event, *, checkpoint=None):
    """Bounded orchestration; optional durable hooks run at authoritative boundaries."""

    def save(stage):
        if checkpoint is not None:
            checkpoint(stage, state)

    if state.status == "completed":
        return state
    if state.active_call is not None:
        raise RuntimeFailure("Ambiguous tool action requires explicit recovery")
    observer = getattr(adapter, "observe", None)
    if observer is not None:
        observer(emit)
    if not state.messages:
        state.messages.append({"role": "user", "content": state.task})
    state.status = "running"
    emit("state", {"status": state.status, "configuration": asdict(config)})
    try:
        while state.pending_calls or state.steps < config.max_steps:
            if state.pending_calls:
                call = ToolCall(**state.pending_calls[0])
                if call.name not in tools:
                    raise RuntimeFailure(f"Unknown tool: {call.name}")
                if state.tool_calls >= config.max_tool_calls:
                    raise RuntimeFailure("Tool budget exhausted")
                state.active_call = asdict(call)
                state.tool_calls += 1
                emit("tool_request", asdict(call))
                save("tool_started")
                value = tools[call.name](copy.deepcopy(call.arguments))
                if inspect.isawaitable(value):
                    async with asyncio.timeout(config.request_timeout):
                        value = await value
                state.working_memory.append(
                    {
                        "name": call.name,
                        "arguments": copy.deepcopy(call.arguments),
                        "result": copy.deepcopy(value),
                    }
                )
                state.messages.append(
                    {"role": "tool", "name": call.name, "content": value}
                )
                state.pending_calls.pop(0)
                state.active_call = None
                emit("tool_result", {"name": call.name, "value": value})
                save("tool_completed")
                continue
            messages = project_context(state, config.context_policy)
            emit(
                "context",
                {
                    "policy": config.context_policy,
                    "message_count": len(messages),
                    "retained_tools": len(state.working_memory),
                },
            )
            for attempt in range(config.max_retries + 1):
                if state.request_attempts >= config.max_steps + config.max_retries:
                    raise RuntimeFailure("Request budget exhausted")
                state.request_attempts += 1
                request_invocations = getattr(adapter, "invocation_count", None)
                state.model_calls += 1
                state.request_in_flight = True
                emit("model_request", {"messages": copy.deepcopy(messages)})
                save("request_started")
                try:
                    async with asyncio.timeout(config.request_timeout):
                        reply = await adapter.complete(copy.deepcopy(messages), config)
                    state.request_in_flight = False
                    break
                except TransientModelError as error:
                    state.request_in_flight = False
                    if state.retries >= config.max_retries:
                        raise RuntimeFailure("Retry budget exhausted") from error
                    state.retries += 1
                    emit("retry", {"reason": str(error), "attempt": attempt + 1})
                    save("retry")
                    await asyncio.sleep(config.retry_delay * 2**attempt)
                except ResponseFailure as error:
                    state.request_in_flight = False
                    state.steps += 1
                    state.model_calls += error.usage.model_calls - 1
                    emit("model_response", {**asdict(error.usage), "failure": True})
                    for name in ("input_tokens", "output_tokens"):
                        old, new = getattr(state, name), getattr(error.usage, name)
                        setattr(
                            state,
                            name,
                            old + new if old is not None and new is not None else None,
                        )
                    raise
                except Exception, asyncio.CancelledError:
                    if request_invocations is not None:
                        state.model_calls += (
                            adapter.invocation_count - request_invocations - 1
                        )
                    state.input_tokens = state.output_tokens = None
                    raise
            state.steps += 1
            state.model_calls += reply.model_calls - 1
            for name in ("input_tokens", "output_tokens"):
                old, new = getattr(state, name), getattr(reply, name)
                setattr(
                    state,
                    name,
                    old + new if old is not None and new is not None else None,
                )
            state.messages.append(
                {
                    "role": "assistant",
                    "content": reply.content,
                    "calls": [asdict(call) for call in reply.calls],
                }
            )
            state.pending_calls = [asdict(call) for call in reply.calls]
            emit("model_response", asdict(reply))
            if not reply.calls:
                state.output = reply.content
                state.status = "completed"
                emit("state", {"status": state.status})
                save("completed")
                return state
            if state.tool_calls + len(reply.calls) > config.max_tool_calls:
                raise RuntimeFailure("Tool budget exhausted")
            save("response")
        raise RuntimeFailure("Step budget exhausted")
    except asyncio.CancelledError:
        if state.status != "completed":
            state.status = "cancelled"
        emit("state", {"status": state.status})
        save("cancelled")
        raise
    except Exception as error:
        state.status = "failed"
        emit("failure", {"category": type(error).__name__})
        save("failed")
        raise

agent_lab/telemetry.py:
"""Scoped, sourced measurements; unavailable telemetry is never fabricated."""

import os
import platform
import shutil
import subprocess
import threading
import time
from pathlib import Path

from agent_lab.experiments import MEASUREMENTS, ROOT, digest


def _read_rss(pid):
    try:
        for line in Path(f"/proc/{pid}/status").read_text().splitlines():
            if line.startswith("VmRSS:"):
                return int(line.split()[1]) * 1024
    except OSError, ValueError:
        return None
    return None


def process_tree(roots, parents):
    result = set(roots)
    while True:
        expanded = result | {pid for pid, parent in parents.items() if parent in result}
        if expanded == result:
            return result
        result = expanded


def memory_snapshot():
    own = _read_rss(os.getpid())
    if own is None:
        return None, None
    backend_pids = set()
    parents = {}
    for path in Path("/proc").iterdir():
        if not path.name.isdigit():
            continue
        try:
            command = (path / "cmdline").read_bytes().split(b"\0")
            parents[int(path.name)] = next(
                int(line.split()[1])
                for line in (path / "status").read_text().splitlines()
                if line.startswith("PPid:")
            )
            if command and Path(os.fsdecode(command[0])).name == "ollama":
                backend_pids.add(int(path.name))
        except OSError:
            continue  # Processes may disappear between enumeration and reading.
    backend_pids = process_tree(backend_pids, parents)
    ram = own + sum(_read_rss(pid) or 0 for pid in backend_pids)
    executable = shutil.which("nvidia-smi")
    if executable is None:
        return ram, None
    try:
        result = subprocess.run(
            [
                executable,
                "--query-compute-apps=pid,used_gpu_memory",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            timeout=2,
            check=False,
        )
    except OSError, subprocess.TimeoutExpired:
        return ram, None
    if result.returncode:
        return ram, None
    try:
        allocations = [
            line.split(",") for line in result.stdout.splitlines() if line.strip()
        ]
        vram = sum(
            int(memory.strip()) * 1024 * 1024
            for pid, memory in allocations
            if int(pid.strip()) in backend_pids | {os.getpid()}
        )
        return ram, vram
    except ValueError:
        return ram, None


class EnergyCounter:
    """One supported RAPL package counter, with explicit measurement scope."""

    def __init__(
        self, read_microjoules, *, max_microjoules, source="measured:RAPL/package"
    ):
        self.read = read_microjoules
        self.maximum = max_microjoules
        self.source = source
        self.initial = None

    def start(self):
        self.initial = self.read()

    def stop(self):
        final = self.read()
        if self.initial is None or final is None:
            return None
        return ((final - self.initial) % self.maximum) / 1e6

    @classmethod
    def discover(cls):
        for path in sorted(Path("/sys/class/powercap").glob("intel-rapl:[0-9]")):
            try:
                maximum = int((path / "max_energy_range_uj").read_text())
                int((path / "energy_uj").read_text())
            except OSError, ValueError:
                continue

            def read(path=path):
                try:
                    return int((path / "energy_uj").read_text())
                except OSError, ValueError:
                    return None

            return cls(
                read,
                max_microjoules=maximum,
                source=f"measured:RAPL/{path.name}/package-only",
            )
        return None


class Telemetry:
    def __init__(
        self,
        *,
        clock=time.perf_counter,
        cpu_clock=time.process_time,
        memory_probe=memory_snapshot,
        energy=None,
        periodic=True,
    ):
        self.clock, self.cpu_clock = clock, cpu_clock
        self.memory_probe, self.energy, self.periodic = memory_probe, energy, periodic
        self.values = dict.fromkeys(MEASUREMENTS)
        self.sources = {}
        self.request_started = None
        self.tool_started = None
        self.model_requests = 0
        self.model_responses = 0
        self.model_metrics_available = True
        self.inference = self.setup = self.tool_time = 0
        self.stop_event = threading.Event()
        self.thread = None

    def sample(self):
        ram, vram = self.memory_probe()
        for key, value in (("peak_ram_bytes", ram), ("peak_vram_bytes", vram)):
            if value is not None:
                self.values[key] = max(self.values[key] or 0, value)

    def _poll(self):
        while not self.stop_event.wait(0.2):
            self.sample()

    def start(self):
        self.started, self.cpu_started = self.clock(), self.cpu_clock()
        if self.energy:
            self.energy.start()
        self.sample()
        if self.periodic:
            self.thread = threading.Thread(target=self._poll)
            self.thread.start()

    def emit(self, kind, payload):
        if kind == "model_request":
            self.model_requests += 1
        elif kind == "model_response":
            self.model_responses += 1
            metrics = payload.get("measurements", {})
            if all(
                key in metrics
                for key in ("load_duration", "prompt_eval_duration", "eval_duration")
            ):
                self.setup += metrics["load_duration"]
                self.inference += (
                    metrics["prompt_eval_duration"] + metrics["eval_duration"]
                )
            else:
                self.model_metrics_available = False
        elif kind == "tool_request":
            self.tool_started = self.clock()
        elif kind == "tool_result" and self.tool_started is not None:
            self.tool_time += self.clock() - self.tool_started
            self.tool_started = None
        if not self.periodic:
            self.sample()

    def stop(self):
        self.stop_event.set()
        if self.thread:
            self.thread.join()
        self.sample()
        ended = self.clock()
        self.values.update(
            wall_seconds=ended - self.started,
            cpu_seconds=self.cpu_clock() - self.cpu_started,
            tool_seconds=self.tool_time
            + (ended - self.tool_started if self.tool_started is not None else 0),
        )
        self.sources.update(
            wall_seconds="measured:perf_counter/end-to-end",
            cpu_seconds="measured:process_time/harness-only",
            tool_seconds="measured:perf_counter/tool-boundaries",
        )
        if self.model_metrics_available and self.model_requests == self.model_responses:
            self.values.update(
                inference_seconds=self.inference, setup_seconds=self.setup
            )
            self.sources.update(
                inference_seconds="reported:backend/prompt+generation",
                setup_seconds="reported:backend/model-load",
            )
        for key, source in (
            (
                "peak_ram_bytes",
                "sampled:/proc/VmRSS/harness+ollama-process-tree/200ms",
            ),
            (
                "peak_vram_bytes",
                "sampled:nvidia-smi/harness+ollama-process-tree/200ms",
            ),
        ):
            if self.values[key] is not None:
                self.sources[key] = source
        if self.energy:
            self.values["energy_joules"] = self.energy.stop()
            if self.values["energy_joules"] is not None:
                self.sources["energy_joules"] = self.energy.source
        return self.values, self.sources


def hardware_profile():
    profile = {
        "architecture": platform.machine(),
        "logical_cpus": os.cpu_count(),
        "cpu": None,
        "ram_bytes": None,
        "gpus": None,
    }
    if Path("/proc/cpuinfo").exists():
        profile["cpu"] = next(
            (
                line.split(":", 1)[1].strip()
                for line in Path("/proc/cpuinfo").read_text().splitlines()
                if line.startswith("model name")
            ),
            None,
        )
        profile["ram_bytes"] = next(
            (
                int(line.split()[1]) * 1024
                for line in Path("/proc/meminfo").read_text().splitlines()
                if line.startswith("MemTotal:")
            ),
            None,
        )
    executable = shutil.which("nvidia-smi")
    if executable:
        try:
            result = subprocess.run(
                [
                    executable,
                    "--query-gpu=name,memory.total,driver_version",
                    "--format=csv,noheader",
                ],
                capture_output=True,
                text=True,
                timeout=2,
                check=False,
            )
            if result.returncode == 0:
                profile["gpus"] = result.stdout.strip().splitlines()
        except OSError, subprocess.TimeoutExpired:
            profile["gpus"] = None
    return {"profile": digest(profile), **profile}


def software_identity():
    files = {
        path.relative_to(ROOT).as_posix(): path.read_text()
        for path in sorted((ROOT / "agent_lab").glob("*.py"))
    }
    return {
        "python": platform.python_version(),
        "platform": platform.platform(),
        "source_hash": digest(files),
    }

agent_lab/trace.py:
"""Versioned ordered metadata, opt-in private content, and strict replay."""

import copy
import hashlib
import json
import os
import tempfile
from dataclasses import asdict
from pathlib import Path

from jsonschema import Draft202012Validator

from agent_lab.experiments import ROOT, canonical, digest
from agent_lab.runtime import Reply, ResponseFailure, TransientModelError


def atomic_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix=path.name + ".", dir=path.parent)
    try:
        with os.fdopen(descriptor, "w") as stream:
            stream.write(canonical(value) + "\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


class Trace:
    def __init__(
        self,
        run_id,
        task_id,
        configuration_id,
        *,
        retain_content=False,
        parent_run_id=None,
    ):
        self.identity = {
            "schema_version": 1,
            "run_id": run_id,
            "task_id": task_id,
            "configuration_id": configuration_id,
            "parent_run_id": parent_run_id,
            "replayable": retain_content,
        }
        self.retain_content = retain_content
        self.events = []
        self.payloads = {}
        self.artifacts = {}

    def emit(self, kind, payload):
        sequence = len(self.events)
        reference = str(sequence) if self.retain_content else None
        public = {}
        if kind == "state":
            public = {"status": payload["status"]}
        elif kind in ("tool_request", "tool_result"):
            public = {"name": payload["name"]} if "name" in payload else {}
        elif kind in ("artifact", "evaluator", "measurements", "authority"):
            public = copy.deepcopy(payload)
        elif kind in ("routing", "child", "context"):
            public = {
                key: payload[key]
                for key in (
                    "stage",
                    "reason",
                    "model_digest",
                    "budget_remaining",
                    "completed_tools",
                    "child_id",
                    "kind",
                    "policy",
                    "message_count",
                    "retained_tools",
                )
                if key in payload
            }
        elif kind == "failure":
            public = {"category": payload["category"]}
        self.events.append(
            {
                "id": f"{self.identity['run_id']}:{sequence}",
                "sequence": sequence,
                "kind": kind,
                "metadata": public,
                "content_ref": reference,
            }
        )
        if self.retain_content:
            self.payloads[reference] = copy.deepcopy(payload)

    def artifact(self, name, path):
        relative = Path(name)
        if relative.is_absolute() or ".." in relative.parts:
            raise ValueError("Artifacts need contained relative names")
        hash_value = hashlib.sha256(Path(path).read_bytes()).hexdigest()
        self.artifacts[relative.as_posix()] = hash_value
        self.emit("artifact", {"path": relative.as_posix(), "sha256": hash_value})

    def document(self):
        return {
            **self.identity,
            "events": copy.deepcopy(self.events),
            "artifacts": dict(self.artifacts),
            "payloads": copy.deepcopy(self.payloads),
        }

    def save(self, path):
        path = Path(path)
        document = self.document()
        payloads = document.pop("payloads")
        if self.retain_content:
            atomic_json(
                path.with_suffix(path.suffix + ".content.json"),
                {
                    "payloads": payloads,
                    "sha256": digest(payloads),
                    "metadata_sha256": digest(document),
                },
            )
        atomic_json(path, document)


def load_trace(path, *, artifact_root=None):
    path = Path(path)
    document = json.loads(path.read_text())
    schema = json.loads((ROOT / "schemas/trace-v1.json").read_text())
    errors = list(Draft202012Validator(schema).iter_errors(document))
    if errors:
        raise ValueError("Invalid trace: " + errors[0].message)
    for index, event in enumerate(document["events"]):
        if event["sequence"] != index or event["id"] != f"{document['run_id']}:{index}":
            raise ValueError("Trace ordering/identity drift")
    if artifact_root is not None:
        root = Path(artifact_root).resolve()
        for name, expected in document["artifacts"].items():
            artifact = (root / name).resolve()
            if not artifact.is_relative_to(root) or not artifact.is_file():
                raise ValueError("Artifact outside root or unavailable")
            if hashlib.sha256(artifact.read_bytes()).hexdigest() != expected:
                raise ValueError(f"Artifact drift: {name}")
    document["payloads"] = {}
    if document["replayable"]:
        private = json.loads(
            path.with_suffix(path.suffix + ".content.json").read_text()
        )
        if digest(private["payloads"]) != private["sha256"]:
            raise ValueError("Private content drift")
        metadata = {key: value for key, value in document.items() if key != "payloads"}
        if digest(metadata) != private["metadata_sha256"]:
            raise ValueError("Trace/content continuation drift")
        document["payloads"] = private["payloads"]
    return document


class Replay:
    def __init__(self, document):
        if not document["replayable"]:
            raise ValueError("Replay requires explicit private content retention")
        self.payloads = document["payloads"]
        self.configuration = next(
            (
                self.payloads[event["content_ref"]]["configuration"]
                for event in document["events"]
                if event["kind"] == "state"
                and "configuration" in self.payloads[event["content_ref"]]
            ),
            None,
        )
        self.events = [
            event
            for event in document["events"]
            if event["kind"]
            in (
                "model_request",
                "model_response",
                "retry",
                "tool_request",
                "tool_result",
            )
        ]
        self.position = 0

    def _next(self, kind):
        if self.position >= len(self.events):
            raise ValueError("Replay exhausted")
        event = self.events[self.position]
        if event["kind"] != kind:
            raise ValueError(f"Replay expected {event['kind']}, received {kind}")
        self.position += 1
        try:
            return copy.deepcopy(self.payloads[event["content_ref"]])
        except KeyError as error:
            raise ValueError("Replay content unavailable") from error

    async def complete(self, messages, config):
        if self.configuration is not None and self.configuration != asdict(config):
            raise ValueError("Configuration drift")
        if self._next("model_request")["messages"] != messages:
            raise ValueError("Model request drift")
        if (
            self.position < len(self.events)
            and self.events[self.position]["kind"] == "retry"
        ):
            raise TransientModelError(self._next("retry")["reason"])
        payload = self._next("model_response")
        if payload.get("failure"):
            raise ResponseFailure(
                "Recorded malformed response",
                input_tokens=payload.get("input_tokens"),
                output_tokens=payload.get("output_tokens"),
                measurements=payload.get("measurements"),
                model_calls=payload.get("model_calls", 1),
            )
        return Reply.parse(payload)

    def tools(self):
        names = {
            self.payloads[e["content_ref"]]["name"]
            for e in self.events
            if e["kind"] == "tool_request"
        }

        def tool(name, arguments):
            request = self._next("tool_request")
            if request != {"name": name, "arguments": arguments}:
                raise ValueError("Tool request drift")
            response = self._next("tool_result")
            if response["name"] != name:
                raise ValueError("Tool result drift")
            return response["value"]

        return {
            name: lambda arguments, name=name: tool(name, arguments) for name in names
        }

    def assert_consumed(self):
        if self.position != len(self.events):
            raise ValueError("Unconsumed replay events")

agent_lab/workspace.py:
"""Keyboard-first local assistant surface backed by runtime checkpoints."""

import argparse
import asyncio
import os
import re
import sys
from pathlib import Path

from agent_lab.experiments import canonical
from agent_lab.permissions import SCOPES, Grant
from agent_lab.workspace_locale import translator
from agent_lab.workspace_store import Workspace

COMMANDS = (
    "start",
    "sessions",
    "attach",
    "run",
    "resume",
    "cancel",
    "inspect",
    "export",
    "history",
    "permissions",
    "grant",
    "memory",
    "settings",
    "abandon",
    "forget",
)


def default_root():
    return (
        Path(os.environ.get("XDG_DATA_HOME", str(Path.home() / ".local/share")))
        / "agent-lab"
    )


def parser_for(translate):
    class Formatter(argparse.HelpFormatter):
        def _format_usage(self, usage, actions, groups, prefix):
            return super()._format_usage(
                usage, actions, groups, prefix or translate("usage") + " "
            )

    class Parser(argparse.ArgumentParser):
        def __init__(self, *args, **kwargs):
            kwargs.update(add_help=False, formatter_class=Formatter)
            super().__init__(*args, **kwargs)
            self._positionals.title = translate("arguments")
            self._optionals.title = translate("options")
            self.add_argument("-h", "--help", action="help", help=translate("help"))

        def error(self, message):
            self.print_usage(sys.stderr)
            self.exit(2, translate("invalid") + "\n")

    parser = Parser(description=translate("title"))
    parser.add_argument(
        "--root", type=Path, default=default_root(), help=translate("root")
    )
    parser.add_argument(
        "--language", choices=("en", "de", "es"), help=translate("language")
    )
    parser.add_argument("--json", action="store_true", help=translate("json"))
    commands = parser.add_subparsers(
        dest="command", required=True, title=translate("commands")
    )
    for command in COMMANDS:
        child = commands.add_parser(
            command, help=translate(command), description=translate(command)
        )
        if command not in ("start", "sessions", "settings"):
            child.add_argument("session", help=translate("session"))
        if command == "start":
            child.add_argument("name", help=translate("name"))
            child.add_argument("project", type=Path, help=translate("project"))
            child.add_argument(
                "--profile", default="medium-q4-gpu", help=translate("profile")
            )
        elif command == "attach":
            child.add_argument("file", type=Path, help=translate("file"))
        elif command == "run":
            child.add_argument("prompt", help=translate("prompt"))
        elif command == "grant":
            child.add_argument("scope", choices=sorted(SCOPES), help=translate("scope"))
            child.add_argument("resource", help=translate("resource"))
            child.add_argument("operation", help=translate("operation"))
            child.add_argument("--reason", required=True, help=translate("reason"))
        elif command == "memory":
            child.add_argument(
                "state", choices=("on", "off", "clear"), help=translate("state")
            )
        elif command == "settings":
            child.add_argument(
                "--set-language", choices=("en", "de", "es"), help=translate("language")
            )
            child.add_argument(
                "--theme", choices=("light", "dark", "system"), help=translate("theme")
            )
    return parser


def _safe(value):
    return re.sub(r"[\x00-\x08\x0b-\x1f\x7f]", "?", str(value))


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    early = argparse.ArgumentParser(add_help=False)
    early.add_argument("--root", type=Path, default=default_root())
    early.add_argument("--language")
    hints, _ = early.parse_known_args(argv)
    workspace = Workspace(hints.root)
    language = hints.language or workspace.preferences()["language"]
    translate = translator(language)
    args = parser_for(translate).parse_args(argv)
    preferences = workspace.preferences()

    def show(message):
        value = _safe(message)
        if sys.stdout.isatty():
            token = {
                "light": "\033[30;47m",
                "dark": "\033[97;40m",
                "system": "\033[36m",
            }.get(preferences["theme"], "\033[36m")
            print(token + value + "\033[0m")
        else:
            print(value)

    def event(kind, payload):
        if kind == "tool_request" and not args.json:
            show(translate("tool", name=translate(payload["name"])))

    try:
        command = args.command
        if command == "start":
            value = workspace.start(args.name, args.project, profile=args.profile)
        elif command == "sessions":
            value = workspace.sessions()
        elif command == "attach":
            value = workspace.attach(args.session, args.file)
        elif command == "run":
            value = asyncio.run(
                workspace.execute(args.session, args.prompt, on_event=event)
            )
        elif command == "resume":
            value = asyncio.run(workspace.resume(args.session, on_event=event))
        elif command == "cancel":
            value = workspace.cancel(args.session)
        elif command == "inspect":
            value = workspace.inspect(args.session)
        elif command == "export":
            value = workspace.export_config(args.session)
        elif command == "history":
            value = workspace.history(args.session)
        elif command == "permissions":
            value = workspace.session(args.session)["permissions"]
        elif command == "grant":
            value = workspace.grant(
                args.session,
                Grant(args.scope, args.resource, args.operation),
                reason=args.reason,
            )
        elif command == "memory":
            value = workspace.memory(
                args.session,
                enabled=None if args.state == "clear" else args.state == "on",
                clear=args.state == "clear",
            )
        elif command == "settings":
            value = workspace.preferences(language=args.set_language, theme=args.theme)
        elif command == "abandon":
            value = workspace.abandon(args.session)
        else:
            value = workspace.forget(args.session)
        if args.json or command == "export":
            print(canonical(value))
        elif command == "start":
            show(translate("started", name=value["name"], id=value["id"]))
        elif command == "attach":
            show(translate("attached", name=value["name"], id=value["id"]))
        elif command == "sessions":
            for session in value:
                show(session["id"] + "  " + session["name"] + "  " + session["profile"])
            if not value:
                show(translate("empty"))
        elif command in ("run", "resume", "inspect"):
            state = value["state"] if command == "inspect" else value
            status = translate(
                "status_failed" if state["status"] == "failed" else state["status"]
            )
            show(
                translate(
                    "summary",
                    status=status,
                    models=state["model_calls"],
                    tools=state["tool_calls"],
                )
            )
            if state["output"]:
                show(state["output"])
            if command == "inspect" and value["trace"]:
                for entry in value["trace"]["events"]:
                    if entry["kind"] == "tool_request" and "name" in entry["metadata"]:
                        show(
                            translate("tool", name=translate(entry["metadata"]["name"]))
                        )
        elif command in ("permissions", "history"):
            for entry in value:
                show(canonical(entry))
        else:
            show(translate("done"))
        return (
            1 if command in ("run", "resume") and value["status"] != "completed" else 0
        )
    except KeyboardInterrupt:
        show(translate("interrupted"))
        return 130
    except Exception as error:
        show(translate("error", category=type(error).__name__))
        return 1


if __name__ == "__main__":
    sys.exit(main())

agent_lab/workspace_store.py:
"""Authoritative local session/run storage; terminal surfaces only reference it."""

import asyncio
import copy
import fcntl
import hashlib
import json
import os
import platform
import re
import secrets
import shutil
import signal
from contextlib import contextmanager
from dataclasses import asdict, replace
from datetime import UTC, datetime
from pathlib import Path

from agent_lab.backends import OllamaAdapter
from agent_lab.baselines import inventory, validate_manifest
from agent_lab.checkpoints import CheckpointStore, run_checkpointed
from agent_lab.experiments import ROOT, canonical, digest
from agent_lab.permissions import Grant, LocalTools, PermissionDenied, Policy
from agent_lab.runtime import AgentConfig, AgentState, FunctionAdapter, Reply, ToolCall
from agent_lab.telemetry import EnergyCounter, Telemetry, hardware_profile
from agent_lab.trace import Trace, atomic_json, load_trace

CORE = (
    "workspace_store.py",
    "runtime.py",
    "context.py",
    "checkpoints.py",
    "permissions.py",
    "backends.py",
    "trace.py",
)


def core_identity():
    return {
        "python": platform.python_version(),
        "runtime_source_sha256": digest(
            {name: (ROOT / "agent_lab" / name).read_text() for name in CORE}
        ),
    }


def _read(path):
    return json.loads(Path(path).read_text())


def _tick(pid):
    return Path(f"/proc/{pid}/stat").read_text().rsplit(")", 1)[1].split()[19]


class Workspace:
    def __init__(self, root):
        self.root = Path(root).resolve()

    def _initialize(self):
        marker = self.root / ".agent-lab-workspace.json"
        if self.root.exists() and any(self.root.iterdir()) and not marker.exists():
            raise ValueError("Workspace history requires an empty dedicated directory")
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)
        os.chmod(self.root, 0o700)
        if not marker.exists():
            atomic_json(marker, {"schema_version": 1, "application": "agent-lab"})

    def _directory(self, identifier):
        if not re.fullmatch(r"[a-f0-9]{16}", identifier):
            raise ValueError("Invalid session identity")
        path = self.root / "sessions" / identifier
        if path.is_symlink():
            raise ValueError("Session directory cannot be a symlink")
        return path

    def session(self, identifier):
        value = _read(self._directory(identifier) / "session.json")
        if value["schema_version"] != 1 or value["id"] != identifier:
            raise ValueError("Session identity drift")
        return value

    def _save_session(self, value):
        atomic_json(self._directory(value["id"]) / "session.json", value)

    def sessions(self):
        return [
            self.session(p.name)
            for p in sorted((self.root / "sessions").glob("*"))
            if p.is_dir()
        ]

    def start(self, name, project, *, profile="medium-q4-gpu"):
        project = Path(project).resolve(strict=True)
        if not project.is_dir() or project.is_relative_to(self.root):
            raise ValueError("Select a project outside private session storage")
        if not isinstance(name, str) or not 1 <= len(name) <= 128:
            raise ValueError("Session name must be bounded")
        if profile == "fixture-demo":
            config = AgentConfig(model="fixture-demo", request_timeout=15)
        else:
            manifest = _read(ROOT / "configurations/local-baselines-v1.json")
            if profile not in manifest["profiles"]:
                raise ValueError("Unknown pinned model profile")
            config = replace(
                AgentConfig(**manifest["profiles"][profile]), request_timeout=15
            )
            validate_manifest(asdict(config), *inventory())
        self._initialize()
        identifier = secrets.token_hex(8)
        directory = self._directory(identifier)
        directory.mkdir(parents=True, mode=0o700)
        grants = [asdict(Grant("repositories", str(project), "read"))]
        value = {
            "schema_version": 1,
            "id": identifier,
            "name": name,
            "project": str(project),
            "profile": profile,
            "configuration": asdict(config),
            "permissions": grants,
            "attachments": [],
            "memory_enabled": False,
            "runs": [],
            "latest_run": None,
            "owner_actions": [
                {
                    "action": "select_project",
                    "approval_id": "owner-start:" + identifier,
                    "owner_uid": os.getuid(),
                    "resource_sha256": digest(str(project)),
                }
            ],
            "created_at": datetime.now(UTC).isoformat(),
        }
        self._save_session(value)
        return value

    def attach(self, identifier, source):
        with self._lease(identifier):
            return self._attach(identifier, source)

    def grant(self, identifier, grant, *, reason):
        with self._lease(identifier):
            return self._grant(identifier, grant, reason=reason)

    def memory(self, identifier, **kwargs):
        with self._lease(identifier):
            return self._memory(identifier, **kwargs)

    def forget(self, identifier):
        with self._lease(identifier):
            return self._forget(identifier)

    def _attach(self, identifier, source):
        session = self.session(identifier)
        source = Path(source).resolve(strict=True)
        native = LocalTools(Policy([Grant("documents", str(source.parent), "read")]))
        text = native.read(
            {"scope": "documents", "root": str(source.parent), "path": source.name}
        )
        if len(text.encode()) > 16384:
            raise ValueError("Text attachments are limited to 16 KiB")
        attachment_id = hashlib.sha256(text.encode()).hexdigest()
        directory = self._directory(identifier) / "attachments"
        directory.mkdir(mode=0o700, exist_ok=True)
        path = directory / attachment_id
        descriptor = os.open(
            path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW, 0o600
        )
        with os.fdopen(descriptor, "w") as stream:
            stream.write(text)
            stream.flush()
            os.fsync(stream.fileno())
        attachment = {"id": attachment_id, "name": source.name, "sha256": attachment_id}
        session.setdefault("owner_actions", []).append(
            {
                "action": "attach_document",
                "approval_id": "owner-attach:" + secrets.token_hex(8),
                "owner_uid": os.getuid(),
                "resource_sha256": attachment_id,
            }
        )
        session["attachments"] = [
            a for a in session["attachments"] if a["id"] != attachment_id
        ] + [attachment]
        grant = asdict(Grant("documents", str(directory), "read"))
        if grant not in session["permissions"]:
            session["permissions"].append(grant)
        self._save_session(session)
        return attachment

    def preferences(self, *, language=None, theme=None):
        path = self.root / "preferences.json"
        values = _read(path) if path.exists() else {"language": "en", "theme": "system"}
        if language is not None:
            if language not in ("en", "de", "es"):
                raise ValueError("Unknown language")
            values["language"] = language
        if theme is not None:
            if theme not in ("light", "dark", "system"):
                raise ValueError("Unknown theme")
            values["theme"] = theme
        if language is not None or theme is not None:
            self._initialize()
            atomic_json(path, values)
        return values

    def _grant(self, identifier, grant, *, reason):
        session = self.session(identifier)
        policy = Policy(Grant(**g) for g in session["permissions"])
        approval_id = "owner-cli:" + secrets.token_hex(8)
        elevated = policy.elevate(grant, reason=reason, approval_id=approval_id)
        session["permissions"] = elevated.document()
        session.setdefault("owner_actions", []).append(
            {
                "action": "grant",
                "grant": asdict(grant),
                "reason": reason,
                "approval_id": approval_id,
                "owner_uid": os.getuid(),
            }
        )
        self._save_session(session)
        return elevated.document()

    def _memory(self, identifier, *, enabled=None, clear=False):
        session = self.session(identifier)
        directory = self._directory(identifier) / "memory"
        if clear and directory.exists():
            shutil.rmtree(directory)
        if clear and session["memory_enabled"]:
            directory.mkdir(mode=0o700, exist_ok=True)
        if enabled is not None:
            session.setdefault("owner_actions", []).append(
                {
                    "action": "memory_control",
                    "approval_id": "owner-memory:" + secrets.token_hex(8),
                    "owner_uid": os.getuid(),
                    "resource_sha256": digest(str(directory)),
                    "enabled": bool(enabled),
                }
            )
            session["memory_enabled"] = bool(enabled)
            session["permissions"] = [
                g for g in session["permissions"] if g["scope"] != "memory"
            ]
            if enabled:
                directory.mkdir(mode=0o700, exist_ok=True)
                session["permissions"] += [
                    asdict(Grant("memory", str(directory), op))
                    for op in ("read", "write")
                ]
            self._save_session(session)
        return {"enabled": session["memory_enabled"], "cleared": clear}

    def _adapter(self, configuration):
        config = AgentConfig(**configuration["agent"])
        if config.backend == "fixture":
            attachments = configuration["attachments"]

            def respond(messages, _):
                if messages[-1]["role"] == "tool":
                    return Reply(
                        str(messages[-1]["content"]), input_tokens=0, output_tokens=0
                    )
                call = (
                    ToolCall("read_attachment", {"id": attachments[0]["id"]})
                    if attachments
                    else ToolCall("read_project", {"path": "README.md"})
                )
                return Reply(calls=(call,), input_tokens=0, output_tokens=0)

            return FunctionAdapter(respond)
        validate_manifest(asdict(config), *inventory())
        return OllamaAdapter()

    def _tools(self, configuration, run_root, emit):
        policy = Policy([Grant(**g) for g in configuration["permissions"]], emit)
        native = LocalTools(policy)
        project = Path(configuration["project"])
        attachments = {a["id"]: a for a in configuration["attachments"]}

        def read_project(args):
            path = Path(args["path"])
            target = (project / path).resolve()
            if any(
                part.startswith(".") or part in ("node_modules", "__pycache__")
                for part in path.parts
            ) or target.is_relative_to(self.root):
                raise PermissionDenied("Private project path unavailable")
            text = native.read(
                {"scope": "repositories", "root": str(project), "path": str(path)}
            )
            if len(text.encode()) > 16384:
                raise ValueError("Project text read exceeds 16 KiB")
            return text

        def list_project(_):
            policy.require("repositories", str(project), "read")
            return sorted(
                p.name
                for p in project.iterdir()
                if not p.name.startswith(".") and not p.is_symlink()
            )[:100]

        def read_attachment(args):
            identifier = args["id"]
            if identifier not in attachments:
                raise PermissionDenied("Attachment not in run configuration")
            root = Path(configuration["attachment_root"])
            text = native.read(
                {"scope": "documents", "root": str(root), "path": identifier}
            )
            if (
                hashlib.sha256(text.encode()).hexdigest()
                != attachments[identifier]["sha256"]
            ):
                raise ValueError("Attachment drift")
            return text

        def remember(args):
            if not configuration["memory_enabled"] or not re.fullmatch(
                r"[a-z0-9-]{1,64}", args["key"]
            ):
                raise PermissionDenied("Memory disabled or key invalid")
            return native.write(
                {
                    "scope": "memory",
                    "root": configuration["memory_root"],
                    "path": args["key"],
                    "content": args["value"],
                }
            )

        def recall(args):
            if not configuration["memory_enabled"] or not re.fullmatch(
                r"[a-z0-9-]{1,64}", args["key"]
            ):
                raise PermissionDenied("Memory disabled or key invalid")
            return native.read(
                {
                    "scope": "memory",
                    "root": configuration["memory_root"],
                    "path": args["key"],
                }
            )

        def add(args):
            numbers = args["numbers"]
            if (
                not isinstance(numbers, list)
                or len(numbers) > 1024
                or any(type(n) is not int for n in numbers)
            ):
                raise ValueError("sum requires at most 1024 integers")
            return sum(numbers)

        registry = {
            "list_project": list_project,
            "read_project": read_project,
            "read_attachment": read_attachment,
            "remember": remember,
            "recall": recall,
            "sum": add,
            "run_process": native.process,
        }
        return registry, {
            "list_project",
            "read_project",
            "read_attachment",
            "recall",
            "sum",
        }

    def _store(self, run_root, configuration, config):
        return CheckpointStore(
            run_root / "checkpoint.json",
            configuration["task_sha256"],
            config,
            idempotent_tools={
                "list_project",
                "read_project",
                "read_attachment",
                "recall",
                "sum",
            },
            artifact_root=run_root,
            tool_identity={
                "permissions": configuration["permissions"],
                "runtime": configuration["software"],
            },
        )

    def _load_latest(self, identifier):
        session = self.session(identifier)
        if session["latest_run"] is None:
            raise ValueError("Session has no run")
        root = self._directory(identifier) / "runs" / session["latest_run"]
        configuration = _read(root / "configuration.json")
        config = AgentConfig(**configuration["agent"])
        state, trace = self._store(root, configuration, config).load()
        return session, root, configuration, config, state, trace

    @contextmanager
    def _lease(self, identifier):
        self.session(identifier)
        descriptor = os.open(
            self._directory(identifier) / "lease", os.O_CREAT | os.O_RDWR, 0o600
        )
        try:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                raise ValueError("Session already has an active operation") from None
            yield
        finally:
            os.close(descriptor)

    async def execute(self, identifier, prompt, **kwargs):
        with self._lease(identifier):
            return await self._execute(identifier, prompt, **kwargs)

    async def resume(self, identifier, **kwargs):
        with self._lease(identifier):
            return await self._resume(identifier, **kwargs)

    def abandon(self, identifier):
        with self._lease(identifier):
            session = self.session(identifier)
            if session["latest_run"] is None:
                raise ValueError("No run to abandon")
            session.setdefault("closed_runs", []).append(session["latest_run"])
            session.setdefault("owner_actions", []).append(
                {"action": "abandon", "run_id": session["latest_run"]}
            )
            self._save_session(session)
            return {"abandoned": session["latest_run"]}

    async def _execute(self, identifier, prompt, *, after_save=None, on_event=None):
        if not isinstance(prompt, str) or not 1 <= len(prompt) <= 16384:
            raise ValueError("Enter a bounded message")
        session = self.session(identifier)
        if session["latest_run"]:
            _, _, _, _, previous, _ = self._load_latest(identifier)
            if previous.status != "completed" and session[
                "latest_run"
            ] not in session.get("closed_runs", []):
                raise ValueError(
                    "Resume or forget the unfinished run before starting a turn"
                )
            previous_messages = (
                copy.deepcopy(previous.messages)
                if previous.status == "completed"
                else []
            )
        else:
            previous_messages = []
        run_id = secrets.token_hex(12)
        root = self._directory(identifier) / "runs" / run_id
        root.mkdir(parents=True, mode=0o700)
        configuration = {
            "schema_version": 1,
            "agent": session["configuration"],
            "project": session["project"],
            "permissions": session["permissions"],
            "owner_actions": session.get("owner_actions", []),
            "attachments": session["attachments"],
            "attachment_root": str(self._directory(identifier) / "attachments"),
            "memory_root": str(self._directory(identifier) / "memory"),
            "memory_enabled": session["memory_enabled"],
            "response_language": self.preferences()["language"],
            "software": core_identity(),
            "hardware": hardware_profile(),
        }
        task = (
            "Return JSON replies with content and calls. Tools: list_project({}), "
            "read_project(path: relative file), read_attachment(id: attachment id), "
            "sum(numbers: array), remember(key,value), recall(key), run_process(argv). "
            "Only declared permissions apply. Memory is "
            + str(session["memory_enabled"])
            + ". Attachments: "
            + canonical(session["attachments"])
            + "\nUser: "
            + prompt
        )
        task += "\nReply in " + configuration["response_language"] + "."
        for name in ("AGENTS.md", "CLAUDE.md"):
            path = Path(session["project"]) / name
            if (
                path.is_file()
                and not path.is_symlink()
                and path.stat().st_size <= 16384
            ):
                task += "\nRepository instructions " + name + ":\n" + path.read_text()
        configuration["task_sha256"] = digest(task)
        atomic_json(root / "configuration.json", configuration)
        trace = Trace(
            run_id,
            "workspace-session",
            digest(configuration),
            parent_run_id=session["latest_run"],
        )
        trace.artifact("configuration.json", root / "configuration.json")
        for action in configuration["owner_actions"]:
            trace.emit(
                "authority",
                {
                    "action": action["action"],
                    "approval_id": action.get("approval_id"),
                    "owner_uid": action.get("owner_uid"),
                    "resource_sha256": action.get(
                        "resource_sha256", digest(action.get("grant", {}))
                    ),
                },
            )
        state = AgentState(
            task,
            messages=previous_messages + [{"role": "user", "content": task}]
            if previous_messages
            else [],
        )
        session["latest_run"] = run_id
        session["runs"].append(run_id)
        self._save_session(session)
        config = AgentConfig(**configuration["agent"])
        self._store(root, configuration, config).save(state, "pending", trace)
        return await self._drive(
            identifier,
            root,
            configuration,
            config,
            state,
            trace,
            after_save=after_save,
            on_event=on_event,
        )

    async def _resume(self, identifier, *, after_save=None, on_event=None):
        session, root, configuration, config, state, trace = self._load_latest(
            identifier
        )
        if (
            configuration["software"] != core_identity()
            or configuration["permissions"] != session["permissions"]
        ):
            raise ValueError("Resume requires original runtime and permissions")
        return await self._drive(
            identifier,
            root,
            configuration,
            config,
            state,
            trace,
            after_save=after_save,
            on_event=on_event,
        )

    async def _drive(
        self,
        identifier,
        root,
        configuration,
        config,
        state,
        trace,
        *,
        after_save=None,
        on_event=None,
    ):
        active = self._directory(identifier) / "active.json"
        if active.exists():
            recorded = _read(active)
            try:
                live = _tick(recorded["pid"]) == recorded["tick"]
            except OSError:
                live = False
            if live:
                raise ValueError("Session already has an active run")
            active.unlink()
        meter = Telemetry(energy=EnergyCounter.discover())

        raw_emit = trace.emit

        def emit(kind, payload):
            raw_emit(kind, payload)
            meter.emit(kind, payload)
            if on_event:
                on_event(kind, payload)

        trace.emit = emit
        failure = None
        try:
            meter.start()
            tools, _ = self._tools(configuration, root, emit)
            adapter = self._adapter(configuration)
            atomic_json(
                active,
                {
                    "pid": os.getpid(),
                    "tick": _tick(os.getpid()),
                    "run_id": trace.identity["run_id"],
                },
            )
            await run_checkpointed(
                adapter,
                tools,
                config,
                state,
                trace,
                self._store(root, configuration, config),
                after_save=after_save,
            )
        except asyncio.CancelledError, KeyboardInterrupt:
            if state.status != "completed":
                state.status = "cancelled"
            raise
        except Exception as error:
            failure = type(error).__name__
            state.status = "failed"
            raw_emit("failure", {"category": failure})
        finally:
            trace.emit = raw_emit
            measurements, sources = meter.stop()
            trace.emit("measurements", {"values": measurements, "sources": sources})
            self._store(root, configuration, config).save(
                state, "session_boundary", trace
            )
            trace.save(root / "trace.json")
            atomic_json(
                root / "summary.json",
                {
                    "status": state.status,
                    "steps": state.steps,
                    "model_calls": state.model_calls,
                    "tool_calls": state.tool_calls,
                    "failure": failure,
                    "measurements": measurements,
                    "measurement_sources": sources,
                },
            )
            active.unlink(missing_ok=True)
        return asdict(state)

    def inspect(self, identifier):
        _, root, configuration, _, state, _ = self._load_latest(identifier)
        trace = (
            load_trace(root / "trace.json", artifact_root=root)
            if (root / "trace.json").exists()
            else None
        )
        return {
            "configuration": configuration,
            "state": asdict(state),
            "trace": trace,
            "summary": _read(root / "summary.json")
            if (root / "summary.json").exists()
            else None,
        }

    def export_config(self, identifier):
        return self.inspect(identifier)["configuration"]

    def history(self, identifier):
        session = self.session(identifier)
        values = []
        for run_id in session["runs"]:
            path = self._directory(identifier) / "runs" / run_id / "summary.json"
            values.append(
                {
                    "run_id": run_id,
                    **(_read(path) if path.exists() else {"status": "pending"}),
                }
            )
        return values

    def cancel(self, identifier):
        active = _read(self._directory(identifier) / "active.json")
        if not hasattr(os, "pidfd_open"):
            raise ValueError("Use Ctrl+C on this platform")
        descriptor = os.pidfd_open(active["pid"])
        try:
            if _tick(active["pid"]) != active["tick"]:
                raise ValueError("Active process identity expired")
            signal.pidfd_send_signal(descriptor, signal.SIGINT)
        finally:
            os.close(descriptor)
        return {"cancel_requested": True}

    def _forget(self, identifier):
        directory = self._directory(identifier)
        self.session(identifier)
        if (directory / "active.json").exists():
            raise ValueError("Cancel the active run before forgetting history")
        shutil.rmtree(directory)
        return {"forgotten": identifier}
